export const demos: DemoEntry[] = [
  { name: "agent-action-approve", title: "Agent Action Approve", description: "Reads an agent's tool call and says plainly what it will delete, send or change, how far it reaches and whether it can be undone. Marks risky tokens, compares the agent's claim with the call, makes dangerous calls hold-to-approve and refuses risky \"always allow\" rules.", category: "Destructive actions", Demo: AgentActionApproveDemo },
  { name: "mcp-tool-review", title: "MCP Tool Review", description: "Review card for MCP tool changes after approval: fingerprints each definition, diffs the description word by word, marks injected instructions (<IMPORTANT> blocks, \"do not tell the user\", ~/.ssh, other servers' tools), new free-text parameters and flipped read-only hints.", category: "Destructive actions", Demo: McpToolReviewDemo },
  { name: "reset-hard-readback", title: "Reset Hard Readback", description: "Readback for destructive git commands from porcelain status: edited files with +/- lines, staged new files, untracked and ignored files (.env and keys first), commits the branch moves past with unpushed ones marked, stash ids to recover, what stays, and a stash-first option.", category: "Destructive actions", Demo: ResetHardReadbackDemo },
  { name: "account-deletion-readback", title: "Account Deletion Readback", description: "Before Delete, lists what goes, sole-owner teams (with transfer), App Store / Google Play plans that keep billing until cancelled there, the restore deadline, what is kept and a data export. Delete unlocks after a typed confirmation and can wait for the paid period to end.", category: "Destructive actions", Demo: AccountDeletionReadbackDemo },
  { name: "force-push-confirm", title: "Force Push Confirm", description: "Lists every commit a force push would drop with author, message and age, marks other people's commits and protected branches, builds a --force-with-lease command pinned to the tip shown (or --force-if-includes), and asks you to type the branch name.", category: "Destructive actions", Demo: ForcePushConfirmDemo },
  { name: "infra-plan-readback", title: "Infra Plan Readback", description: "Reads a `terraform show -json` plan as create, update, replace and destroy counts, lists stateful destroys and replacements first with the attribute forcing each, and keeps Apply locked until each loss is acknowledged (and, in production, the workspace typed).", category: "Destructive actions", Demo: InfraPlanReadbackDemo },
  { name: "recovery-contact-cooldown", title: "Recovery Contact Cooldown", description: "Shows a pending recovery-contact change: the masked new contact, a countdown to when it applies, that codes still go to the old contact, an urgent state in the last hour, a cancel button and a \"this wasn't me\" path. Announces the outcome, not the ticking.", category: "Destructive actions", Demo: RecoveryContactCooldownDemo },
  { name: "migration-preview", title: "Migration Preview", description: "Postgres migration reader (strings, dollar quotes, comments handled) showing what each step locks, which rewrite big tables and which drops can't be undone, and catching failing NOT NULL adds, mid-deploy renames, CONCURRENTLY in a transaction and no lock_timeout.", category: "Destructive actions", Demo: MigrationPreviewDemo },
  { name: "feature-flag-rollout", title: "Feature Flag Rollout", description: "Reads back who gets the flag (segments plus a percentage of everyone else, in users), asks for a second click before production skips ramp steps or gets ahead of staging, and warns how many users lose the feature on a pullback.", category: "Destructive actions", Demo: FeatureFlagRolloutDemo },
  { name: "branch-target", title: "Branch Target", description: "Checks the chosen base against branch rules (feature → main is caught, with a one-tap switch to develop), counts commits the branch would drag in that aren't its own, and flags a head that is behind its target with an Update branch action.", category: "Destructive actions", Demo: BranchTargetDemo },
  { name: "session-list", title: "Session List", description: "Signed-in sessions list with this device pinned and marked, \"Sign out all others\" that never includes it, an inline confirm (Cancel focused) before signing out here, and sessions from another country flagged with \"approximate location\" wording.", category: "Destructive actions", Demo: SessionListDemo },
  { name: "sign-in-approve", title: "Sign-in Approve", description: "Sign-in approval prompt with no one-tap Approve: the user types the number from the sign-in screen, sees location and device, is warned about request bursts and \"support\" asking for codes, and every denial ends on a secure-my-account step.", category: "Destructive actions", Demo: SignInApproveDemo },
  { name: "hold-to-confirm", title: "Hold to Confirm", description: "Button that runs onConfirm only after a full press-and-hold by mouse, touch or keyboard, rewinds on early release, shows \"Hold to confirm\" on a plain click, and lets users who can't hold (screen reader, switch access) confirm with a second press.", category: "Destructive actions", Demo: HoldToConfirmDemo },
  { name: "two-step-button", title: "Two-Step Button", description: "Destructive button where the first click arms it with a draining timer and a second deliberate click confirms; accidental double-clicks, held keys, blur, Escape or the timeout all disarm it.", category: "Destructive actions", Demo: TwoStepButtonDemo },
  { name: "slide-to-confirm", title: "Slide to Confirm", description: "Slide-to-confirm control where the thumb must travel the whole track (threshold), a held arrow key stops short of the end, an async confirm shows a pending state, and a rejection slides it back.", category: "Destructive actions", Demo: SlideToConfirmDemo },
  { name: "type-to-confirm", title: "Type to Confirm", description: "GitHub-style confirm dialog (native <dialog>) that unlocks only after the exact phrase is typed, highlighting matched characters and flagging a typo the moment it happens; errors keep the dialog open.", category: "Destructive actions", Demo: TypeToConfirmDemo },
  { name: "undo-toast", title: "Undo Toast", description: "Deferred actions with an undo window: actions apply optimistically and commit only after a countdown that pauses on hover, focus or a hidden tab, with Ctrl/⌘+Z, a commit on page close (pagehide), and a rollback notice if the commit fails.", category: "Destructive actions", Demo: UndoToastDemo },
  { name: "impact-preview", title: "Impact Preview", description: "Delete confirmation that loads every dependent of a parent object, grouped by type with counts and samples and marked deleted, detached or kept, and keeps Confirm locked until the list has loaded.", category: "Destructive actions", Demo: ImpactPreviewDemo },
  { name: "bulk-scope-confirm", title: "Bulk Scope Confirm", description: "States the exact count and risky subsets (\"including 12 you don't own\"), defaults to only the selected items on this page, and locks Confirm if the match count changes while the dialog is open.", category: "Destructive actions", Demo: BulkScopeConfirmDemo },
  { name: "drop-confirm", title: "Drop Confirm", description: "The target names exactly what will move and where, ignores a drop before the pointer has rested on it, asks once before large moves or moves that change who can see the items, and offers Undo, with a Move here button for keyboard and touch.", category: "Destructive actions", Demo: DropConfirmDemo },
  { name: "danger-zone", title: "Danger Zone", description: "Destructive actions stay listed with their consequences but locked until the user deliberately unlocks the section, which relocks after one action, an idle timeout (60 s default), Escape, a hidden tab or focus leaving it.", category: "Destructive actions", Demo: DangerZoneDemo },
  { name: "click-shield", title: "Click Shield", description: "Wraps a control and ignores pointer presses for about 500 ms after it appears, shifts, changes its label or the tab regains focus, with a quiet fade-in cue. Keyboard users are only shielded from focus that code moved onto the control.", category: "Destructive actions", Demo: ClickShieldDemo },
  { name: "shortcut-confirm", title: "Shortcut Confirm", description: "Two-press guard for destructive shortcuts: the first press shows \"Press ⌘⌫ again to delete 3 items\", and only a separate second press within the window confirms. Held keys, extra modifiers, stray keys in between and keystrokes in text fields don't count.", category: "Destructive actions", Demo: ShortcutConfirmDemo },
  { name: "guarded-switch", title: "Guarded Switch", description: "Toggle for critical settings with a see-through cover, like an aircraft switch guard: lift it first, it states what flipping will do while open, drops back on its own after a few seconds, and reads back the consequence after the change. Red tone for irreversible effects.", category: "Destructive actions", Demo: GuardedSwitchDemo },
  { name: "swipe-delete-row", title: "Swipe Delete Row", description: "Swipe-to-delete row that deletes only when dragged past a visible line (not on a fast flick or vertical scroll), resists like a rubber band, springs back if released early, has a trash button for keyboard users and keeps an Undo before the delete commits.", category: "Destructive actions", Demo: SwipeDeleteRowDemo },
  { name: "grace-send", title: "Grace Send", description: "Send button with a grace window: pressing it starts a countdown ring before your onSend runs, so Cancel, Escape or a leave-page warning can stop it; Send now skips the wait. Shows pending, sent, cancelled and failed states.", category: "Destructive actions", Demo: GraceSendDemo },
  { name: "two-person-approve", title: "Two-Person Approve", description: "Approval UI for high-risk actions that surfaces the two-person rule: the requester can't approve their own request here, approval is tied to a fingerprint of the exact plan so edits need re-review, rejections need a reason, and expired requests can't be approved.", category: "Destructive actions", Demo: TwoPersonApproveDemo },
  { name: "trash-countdown", title: "Trash Countdown", description: "Trash list showing time left before each item is purged, highlighting soon-to-go items, with one-tap restore, and an empty-trash confirm that needs the typed item count and resets if new items arrive mid-confirmation.", category: "Destructive actions", Demo: TrashCountdownDemo },
  { name: "range-select-guard", title: "Range Select Guard", description: "Selectable list that reads back how many rows a shift-click range selected (with Undo), skips and reports rows hidden by the filter, flags rows on pages never opened with an \"only this page\" fix, and calls out selected rows a filter now hides.", category: "Destructive actions", Demo: RangeSelectGuardDemo },
  { name: "reauth-gate", title: "Reauth Gate", description: "Step-up prompt for sensitive actions. Checks a passkey, password or PIN through your own verify function, names the action and why it asks, runs the queued action after confirmation, and remembers it for a short window shown as an endable countdown chip.", category: "Destructive actions", Demo: ReauthGateDemo },
  { name: "rollback-preview", title: "Rollback Preview", description: "Rollback confirmation listing what reverts, what won't undo (irreversible migrations, data written since), the target's age and every newer version skipped. Confirms only when the target's name is typed, and calls out a different version's name instead of silently not matching.", category: "Destructive actions", Demo: RollbackPreviewDemo },
  { name: "edit-lock", title: "Edit Lock", description: "Locks the form in a disabled fieldset (\"Locked by Priya after approval\"), says before unlocking that any change needs re-approval, voids the approval only when something actually changes, and relocks after idleness, never mid-typing.", category: "Destructive actions", Demo: EditLockDemo },
  { name: "archive-or-delete", title: "Archive or Delete", description: "Shows Archive and Delete together with each affected thing's fate under both. The reversible choice starts selected and focused so Enter archives; choosing Delete highlights what is lost and relabels the button \"Delete forever\".", category: "Destructive actions", Demo: ArchiveOrDeleteDemo },
  { name: "revoke-access-preview", title: "Revoke Access Preview", description: "Pre-removal readback for members, tokens or apps: what they lose, what they own with a reassign picker and one-tap reassign-all, sessions that end (flagging any in use now) and integrations that stop on their credentials. The button says if anything stays unowned.", category: "Destructive actions", Demo: RevokeAccessPreviewDemo },
  { name: "transfer-ownership", title: "Transfer Ownership", description: "Ownership transfer that reads back what moves and what you keep, warns when the email is outside your org with a one-tap switch to the colleague you probably meant, blocks a recipient whose plan can't own it, and transfers only once they accept, showing the pending request.", category: "Destructive actions", Demo: TransferOwnershipDemo },
  { name: "cancel-readback", title: "Cancel Readback", description: "The cancel screen reads back the exact date and time access ends, what is lost and kept, and the refund (or plainly that there is none), offers pause or downgrade once below a cancel button that never moves, and ends on a receipt with undo.", category: "Destructive actions", Demo: CancelReadbackDemo },
  { name: "merge-records", title: "Merge Records", description: "Duplicate merge panel where each field defaults to the most recent non-empty value, real conflicts are marked (ignoring case and spacing), and a live readback names every value that will be discarded, which record keeps its ID and which links move to it.", category: "Destructive actions", Demo: MergeRecordsDemo },
  { name: "move-readback", title: "Move Readback", description: "Move confirmation that reads back the destination path with the folder setting access highlighted, how many people gain or lose access, path links that break (with a redirect option) and inherited settings that change, and relabels the button when access widens.", category: "Destructive actions", Demo: MoveReadbackDemo },
  { name: "reset-preview", title: "Reset Preview", description: "Reset-to-defaults preview listing only the settings the user changed as current → default, with per-setting keep checkboxes, an export nudge until a copy is saved, and a draining Undo after the reset.", category: "Destructive actions", Demo: ResetPreviewDemo },
  { name: "replace-file", title: "Replace File", description: "Name-clash resolver for uploads: both copies side by side with thumbnail, size and date, a warning plus one-tap Keep both when an older file would replace a newer one, identical copies spotted, renamed-copy preview, and apply-to-all with counts.", category: "Destructive actions", Demo: ReplaceFileDemo },
  { name: "dns-record-guard", title: "DNS Record Guard", description: "Checks a DNS change against the zone: a removed MX, SPF senders dropped or past the 10-lookup limit, a removed DKIM selector (escalated under enforcing DMARC), a CNAME at the root or beside other records and dangling names, then says how long it takes to spread.", category: "Destructive actions", Demo: DnsRecordGuardDemo },
  { name: "key-rotate", title: "Key Rotate", description: "Rotation panel that keeps old and new API keys valid until a stated time, shows which clients use the new key, flags rare jobs that won't call before the old key expires, and holds an immediate cut-off while the old key is in use unless it leaked.", category: "Destructive actions", Demo: KeyRotateDemo },
  { name: "retention-change", title: "Retention Change", description: "Retention picker that states what a shorter period deletes and when (\"deletes 14,210 events older than 13 Sep, tonight at 02:00\"), shades the doomed days on a chart, counts down while undoing is still free, and labels confirm \"Delete without export\" until exported.", category: "Destructive actions", Demo: RetentionChangeDemo },
  { name: "seat-reduce", title: "Seat Reduce", description: "Seat-reduction flow that asks who goes, suggests unaccepted invites then least-active members (never owners or admins), warns when you pick an admin or someone active today, and shows the new bill, when it starts and what happens to each person's work.", category: "Destructive actions", Demo: SeatReduceDemo },
  { name: "cooldown-button", title: "Cooldown Button", description: "Escalating cooldowns per attempt (30s, 60s, 120s) with a visible countdown and reason, and a lock once attempts run out. The deadline is kept in sessionStorage, so a refresh in the same tab keeps it; a new tab or cleared storage does not.", category: "Submits and rate limits", Demo: CooldownButtonDemo },
  { name: "safe-submit", title: "Safe Submit", description: "Submit button that runs one request at a time, ignores repeat clicks, Enter spam and double-taps, and hands your onSubmit an idempotency key that is reused on retry after a network error or 408/429/5xx so the server can dedupe.", category: "Submits and rate limits", Demo: SafeSubmitDemo },
  { name: "bulk-runner", title: "Bulk Runner", description: "Shows live done/failed/remaining counts. Pause and Stop let in-flight items finish, then say exactly what was and wasn't done. Failures are grouped by reason with retry-failed-only, and progress never jumps backwards.", category: "Submits and rate limits", Demo: BulkRunnerDemo },
  { name: "spend-cap-button", title: "Spend Cap Button", description: "Buy button that remembers recent purchases of the same item (\"You bought this 3 min ago\") and needs a deliberate second click to buy again, previews the purchase against each cap, and refuses in the UI any spend that would break a cap, with the overage and reset time.", category: "Submits and rate limits", Demo: SpendCapButtonDemo },
  { name: "scheduled-queue", title: "Scheduled Queue", description: "Queue of scheduled sends that counts down each row, highlights the last-chance window before the real cancel cutoff, offers a one-tap move for sends landing in quiet hours where the audience lives, flags missed sends, and refuses past reschedule times.", category: "Submits and rate limits", Demo: ScheduledQueueDemo },
  { name: "commit-combobox", title: "Commit Combobox", description: "Unpicked text is matched on blur (an exact match is picked, a misspelling gets a Did you mean, duplicate names ask which), editing after a pick visibly drops it with Undo or Esc, and the stored option is always read back.", category: "Validators", Demo: CommitComboboxDemo },
  { name: "relative-date-input", title: "Relative Date Input", description: "Reads \"next Fri\", \"in 2 weeks\", \"the 15th\" or \"23 Oct\" against today with date-fns. When a phrase can mean two dates (\"next Friday\" on a Wednesday, \"the 10th\" once passed), it shows both and waits for a pick, then offers a rewrite to the explicit date.", category: "Validators", Demo: RelativeDateInputDemo },
  { name: "namesake-select", title: "Namesake Select", description: "Person picker that flags options sharing a name (ignoring case, accents and word order) with only the details that tell them apart, asks for one identifier before a shared name becomes the value, offers a switch when the answer fits the other person, and reads the choice back.", category: "Validators", Demo: NamesakeSelectDemo },
  { name: "cheque-check", title: "Cheque Check", description: "Reads the date as written in the CTS boxes (so 31 November is caught), shows the safe deposit window under RBI's three-month rule with a warning on the disputed last day, catches stale January dates and two-digit years, and says when Positive Pay applies.", category: "Validators", Demo: ChequeCheckDemo },
  { name: "kyc-name-match", title: "KYC Name Match", description: "KYC name field that compares the typed name with each document word by word (order, initials, missing middle name, transliterations like Laxmi/Lakshmi), checks the PAN's 4th and 5th letters, flags differing date of birth or gender, and offers each exact name.", category: "Validators", Demo: KycNameMatchDemo },
  { name: "aadhaar-input", title: "Aadhaar Input", description: "Masks Aadhaar entry as XXXX XXXX 1234 (reveal on demand), checks the Verhoeff check digit and the no-0-or-1 first digit, recognises a VID, enrolment ID, masked copy, PAN or mobile pasted by mistake, strips photocopy separators and says how the number is stored.", category: "Validators", Demo: AadhaarInputDemo },
  { name: "password-policy-input", title: "Password Policy Input", description: "Password policy editor that checks rules against NIST SP 800-63B-4 (composition rules, forced rotation, security questions, hints, minimum under 15 or 8 with MFA, maximum under 64, blocked paste, no breach check or attempt limit), shows sample passwords and applies defaults.", category: "Validators", Demo: PasswordPolicyInputDemo },
  { name: "passenger-name-input", title: "Passenger Name Input", description: "Passenger name field that checks against the ID and catches swapped names, a missing middle name, titles, suffixes or nicknames in the name, single-name passengers, accents the ticket can't print and names over the airline's limit, with fixes and a SURNAME/GIVEN TITLE readback.", category: "Validators", Demo: PassengerNameInputDemo },
  { name: "email-change-guard", title: "Email Change Guard", description: "Catches misspelled providers (gmial.con) with a one-tap fix, shows where the confirmation stops matching, spots the same inbox (Gmail dots, +tags), says what moves with the address, and keeps the old address active until the new one is verified, with resend, edit and cancel.", category: "Validators", Demo: EmailChangeGuardDemo },
  { name: "invoice-number-check", title: "Invoice Number Check", description: "GST invoice number field that counts to 16, names characters other than letters, digits, - or /, catches a number already used this financial year (case-insensitively), a stale year token, skipped or reused counters and gaps, and offers the next number.", category: "Validators", Demo: InvoiceNumberCheckDemo },
  { name: "pin-drop-check", title: "Pin Drop Check", description: "Map-pin check that measures the pin against the geocoded address and PIN area (ignoring gaps inside GPS accuracy), flags pins in water or on a highway from your geo helper, draws the gap on a to-scale SVG sketch with no map library, and asks \"Use pin or address?\".", category: "Validators", Demo: PinDropCheckDemo },
  { name: "pincode-input", title: "PIN Code Input", description: "Indian PIN field that reads the state from the first digits offline and flags a mismatch with the picked state, catches O typed for 0, wrong lengths, unused prefixes, Army Post codes and ZIP or UK postcodes typed for India, then checks the area and city through your lookup.", category: "Validators", Demo: PincodeInputDemo },
  { name: "password-hint-guard", title: "Password Hint Guard", description: "Hint or security-answer field that spots the password inside it (also backwards, spaced out or in leetspeak), a large piece of it, or a \"same as my bank\" reuse admission, without displaying the password, and removes the leak in one tap.", category: "Validators", Demo: PasswordHintGuardDemo },
  { name: "coupon-input", title: "Coupon Input", description: "Cleans pasted spaces, hidden characters and case, catches O-vs-0 look-alikes with a fix, says why a code didn't apply (cart minimum and the gap, expiry, excluded items, already used), shows the real saving and any cap, and asks before a worse code replaces a better one.", category: "Validators", Demo: CouponInputDemo },
  { name: "paste-target-guard", title: "Paste Target Guard", description: "Payment-target field that compares what lands in it with what was copied on the page or entered earlier, flags look-alikes of saved recipients, and shows both side by side in groups (ends first, differing characters marked) with the original one tap away.", category: "Validators", Demo: PasteTargetGuardDemo },
  { name: "email-input", title: "Email Input", description: "Spots misspelled domains like gmial.con or rediffmial.com with Damerau-Levenshtein matching and offers a one-tap, never automatic, fix; can suggest matching providers while the domain is being typed.", category: "Validators", Demo: EmailInputDemo },
  { name: "password-input", title: "Password Input", description: "Password field that warns as it happens about Caps Lock, a non-Latin keyboard layout (from the physical key vs the character typed) and leading or trailing spaces from a paste, with a one-tap trim and a press-and-hold or toggle peek.", category: "Validators", Demo: PasswordInputDemo },
  { name: "match-field", title: "Match Field", description: "Enter-twice field for passwords and account numbers that shows the position where the confirmation stops matching without revealing either value, and refuses a paste into the confirm box only when it is a copy of the first entry, so password managers keep working.", category: "Validators", Demo: MatchFieldDemo },
  { name: "amount-input", title: "Amount Input", description: "Groups digits live with Intl.NumberFormat (lakh/crore for en-IN), spells the amount cheque-style, and when you pass `typical` warns about an amount 10× or more above or below it, with a one-tap fix. Reports the value as a JavaScript number.", category: "Validators", Demo: AmountInputDemo },
  { name: "date-sanity-input", title: "Date Sanity Input", description: "Reads the weekday back and catches year typos, past or future dates on the wrong side of today (per `expect`), dates implausibly far away and weekends, each with a one-tap fix.", category: "Validators", Demo: DateSanityInputDemo },
  { name: "clean-paste-input", title: "Clean Paste Input", description: "Strips zero-width, BOM, soft-hyphen and bidi control characters on paste, says what was removed with an undo, and flags any that arrive by typing or autofill with a one-tap fix.", category: "Validators", Demo: CleanPasteInputDemo },
  { name: "otp-paste-input", title: "OTP Paste Input", description: "One-time-code field that extracts the code from a pasted SMS or email, skipping phone numbers, amounts, account endings and order numbers (a run near \"code\" or \"OTP\" wins), and accepts digits typed or pasted in any script (full-width, Devanagari, Arabic-Indic).", category: "Validators", Demo: OtpPasteInputDemo },
  { name: "url-input", title: "URL Input", description: "URL field that adds a missing https://, flags http, Cyrillic or Greek lookalike hostnames (decoding punycode) and a \"paypal.com@\" prefix that hides the real site, fixes typo'd endings like .con, trims sentence leftovers and strips tracking parameters in one tap.", category: "Validators", Demo: UrlInputDemo },
  { name: "phone-input", title: "Phone Input", description: "Phone field that cleans pasted input (separators, a leading 0, a doubled +91), picks the country from the dial and area code (+1 416 is Canada), warns on wrong digit counts, checks ranges and line types with libphonenumber, and reads back the E.164 value.", category: "Validators", Demo: PhoneInputDemo },
  { name: "char-budget", title: "Character Budget", description: "Counts graphemes against several limits at once (X, SMS segments, LinkedIn, meta description), names the curly quote or emoji that forced UCS-2 SMS encoding, and can swap them for plain characters in one tap.", category: "Validators", Demo: CharBudgetDemo },
  { name: "code-input", title: "Code Input", description: "Disables autocorrect, autocapitalise and spellcheck, catches smart quotes, en/em dashes, ellipses and hidden characters by line and column with a one-tap fix, and can validate JSON.", category: "Validators", Demo: CodeInputDemo },
  { name: "inline-edit", title: "Inline Edit", description: "Click-to-edit text: a cancelled edit can be restored, a failed save keeps your draft, and a value changed by someone else mid-edit is flagged instead of silently overwritten (clicking away then keeps the editor open rather than saving).", category: "Validators", Demo: InlineEditDemo },
  { name: "checksum-input", title: "Checksum Input", description: "Checks mod-97 (IBAN), Luhn (card) and ISBN check digits, IBAN country lengths and IFSC format as you type, then highlights the one swapped or doubled character that explains a failure instead of guessing a digit.", category: "Validators", Demo: ChecksumInputDemo },
  { name: "name-input", title: "Name Input", description: "Name field that spots caps lock, all-lowercase, stray digits, doubled spaces and a first/last mix-up, and offers, never forces, a fix cased the way McDonald, O'Brien, van der Berg and de la Cruz are really written, with a Keep option.", category: "Validators", Demo: NameInputDemo },
  { name: "near-duplicate-input", title: "Near-Duplicate Input", description: "Create field that spots near-duplicates as you type (capitals, spacing, punctuation, plurals, one-letter typos, never different numbers like Q3 vs Q4) and offers Use existing, which is also what Enter does.", category: "Validators", Demo: NearDuplicateInputDemo },
  { name: "slug-input", title: "Slug Input", description: "Slug field that follows the title with proper transliteration (Straße → strasse) until published, reads back the full URL, checks collisions as you type with the next free slug one tap away, and warns that editing a live slug breaks links, keeping a redirect by default.", category: "Validators", Demo: SlugInputDemo },
  { name: "homoglyph-guard", title: "Homoglyph Guard", description: "Username and domain field that detects look-alike, mixed-script, styled (math bold, fullwidth) and zero-width characters following UTS #39 ideas, names each character's script and code point, flags imitations of protected names, and offers the plain-ASCII version in one tap.", category: "Validators", Demo: HomoglyphGuardDemo },
  { name: "contrast-picker", title: "Contrast Picker", description: "Shows the WCAG 2 contrast ratio truncated, never rounded up (#777 on white is 4.47:1 and fails), with AA/AAA marks for normal and large text, and a one-tap nearest passing colour that changes only lightness so the hue stays on brand.", category: "Validators", Demo: ContrastPickerDemo },
  { name: "address-check", title: "Address Check", description: "Catches a missing flat or house number, a postcode that doesn't fit the country (or fits another one), a city the postcode lookup places elsewhere and PO boxes couriers can't reach, with one-tap fixes and a live readback of the printed label.", category: "Validators", Demo: AddressCheckDemo },
  { name: "tax-id-input", title: "Tax ID Input", description: "Tax number field for GSTIN, PAN and EU VAT that recomputes the GSTIN's mod-36 check character, reads back state, holder type and country, and pinpoints the wrong character with a one-tap fix for look-alikes, swaps and GR instead of EL.", category: "Validators", Demo: TaxIdInputDemo },
  { name: "filename-input", title: "Filename Input", description: "Selects only the base name on focus, warns with a one-tap undo when the extension changes or disappears, and catches illegal characters, Windows reserved names (CON, NUL.txt), trailing dots and spaces, over-long names and duplicates differing only in case.", category: "Validators", Demo: FilenameInputDemo },
  { name: "coordinate-input", title: "Coordinate Input", description: "Reads decimal, DMS and pasted map links (taking Google's pin, not the map centre), catches swapped latitude and longitude, flipped west/south signs against an expected area and 0, 0 defaults, and reads each point back with an OpenStreetMap link.", category: "Validators", Demo: CoordinateInputDemo },
  { name: "zero-result-rescue", title: "Zero Result Rescue", description: "Empty-search helper that explains what got in the way and offers only fixes that return results: did-you-mean from your vocabulary, the query retyped in the right layout or without Caps Lock, dropping the filter that hides everything, or all categories, each with a count.", category: "Validators", Demo: ZeroResultRescueDemo },
  { name: "mixed-value-field", title: "Mixed Value Field", description: "Bulk-edit field that shows \"Mixed (3 values)\" with the distribution instead of a blank or the first record's value, leaves each record alone unless you pick a value, and reads back exactly what saving changes, counting only records that actually change.", category: "Validators", Demo: MixedValueFieldDemo },
  { name: "card-expiry-input", title: "Card Expiry Input", description: "Masks MM/YY, reads the date back as valid through the month's last day, and catches month 13, the year typed first, a four-digit year, an expired card and one that runs out before the next renewal, with one-tap fixes.", category: "Validators", Demo: CardExpiryInputDemo },
  { name: "username-input", title: "Username Input", description: "Username field that reads back the exact stored handle, blocks reserved words even in disguise (adm1n) and case-only duplicates, flags lookalikes of existing names with a UTS #39-style skeleton, and checks availability after a pause with free alternatives.", category: "Validators", Demo: UsernameInputDemo },
  { name: "ifsc-input", title: "IFSC Input", description: "IFSC field that catches the letter O typed for the fixed zero, a missing 0, digits in the bank code and guessed prefixes (AXIS for UTIB), then reads the branch back from your lookup (Razorpay IFSC API shape) and warns when it belongs to a different bank than the one picked.", category: "Validators", Demo: IfscInputDemo },
  { name: "upi-id-input", title: "UPI ID Input", description: "UPI ID field that cleans pasted upi://pay links and catches emails, typo'd handles (@okaxsi), app names as handles (@gpay), wrong-length or +91 phone IDs and older @paytm IDs, then reads back the registered name from your check and flags a mismatch.", category: "Validators", Demo: UpiIdInputDemo },
  { name: "shortcut-recorder", title: "Shortcut Recorder", description: "Shortcut recorder that checks the combo against browser and OS reserved keys on every platform (Ctrl+W, ⌘Q, Ctrl+T), the app's own bindings and keys that need AltGr on some layouts, then reads it back as ⌘ on Mac and Ctrl on Windows/Linux.", category: "Validators", Demo: ShortcutRecorderDemo },
  { name: "hashtag-input", title: "Hashtag Input", description: "Hashtag field that flags characters ending a tag early (spaces, apostrophes), all-digit tags that never link, case-only duplicates, banned tags and posts over a platform's limit, and suggests CamelCase (#OpenSource) so screen readers say the words. One-tap fixes.", category: "Validators", Demo: HashtagInputDemo },
  { name: "timezone-picker", title: "Timezone Picker", description: "Time zone search by city, country or abbreviation, listing every meaning of ambiguous abbreviations (IST, CST) instead of guessing, with local time and UTC offset per result, warnings for an upcoming clock change and a zone that differs from the device's.", category: "Validators", Demo: TimezonePickerDemo },
  { name: "scope-picker", title: "Scope Picker", description: "API-key scope picker that reads back in plain words what the key can do (destructive powers in red), flags write, delete and admin scopes, offers \"Only what you've used\" from real usage, and warns when the key never expires.", category: "Validators", Demo: ScopePickerDemo },
  { name: "brand-color-input", title: "Brand Color Input", description: "Names the closest palette token with a perceptual (OKLab) distance and offers a one-tap snap when a value is slightly off (#1e40ae vs #1e40af); catches pasted junk, O for 0, wrong digit counts, alpha in 4/8-digit hex and Android #AARRGGBB order.", category: "Validators", Demo: BrandColorInputDemo },
  { name: "wrong-layout-input", title: "Wrong Layout Input", description: "Text input that catches text typed in the wrong keyboard layout (Russian, Hebrew, Greek, Hindi InScript against US QWERTY) using letter-pair models, offers the retyped text as a one-tap fix with undo, and leaves names, acronyms, links and code alone.", category: "Validators", Demo: WrongLayoutInputDemo },
  { name: "fx-send-receive", title: "FX Send Receive", description: "Send/receive pair for international transfers. Locks the side you typed, works out the other from rate and fees, compares what arrives with the invoice, and flags the invoice typed into \"You send\", a currency mismatch, SHA deductions and overpaying, with one-tap fixes.", category: "Readbacks and calculators", Demo: FxSendReceiveDemo },
  { name: "epoch-input", title: "Epoch Input", description: "Reads the value back in the user's zone and UTC, and catches milliseconds pasted as seconds, micro- and nanoseconds, Excel serials, Windows FILETIME, .NET ticks, ISO strings without a zone, date-only strings read as UTC midnight and impossible dates like 30 Feb.", category: "Readbacks and calculators", Demo: EpochInputDemo },
  { name: "notice-period-check", title: "Notice Period Check", description: "Notice calculator that works out the last day from the resignation and policy (days, weeks or months; calendar or working days) and flags month-end arithmetic, weekend or holiday last days, HR's time zone dating the email differently, unpaid leave, leave set-off and buyout cost.", category: "Readbacks and calculators", Demo: NoticePeriodCheckDemo },
  { name: "tax-regime-compare", title: "Tax Regime Compare", description: "Old vs new regime tax for salaried residents in India, tax year 2026-27, from salary, HRA (50% cities per rule 279), 80C, 80D, NPS and home-loan interest. Shows break-even deductions and flags a costlier choice, deductions the new regime ignores and over-limit claims.", category: "Readbacks and calculators", Demo: TaxRegimeCompareDemo },
  { name: "emi-readback", title: "EMI Readback", description: "Reads back EMI, total interest, processing fee with GST, other upfront charges, the amount that reaches the account and the APR computed as in RBI's Key Facts Statement, catching tenure in the wrong unit, monthly rates typed as yearly, flat rates and heavy fees.", category: "Readbacks and calculators", Demo: EmiReadbackDemo },
  { name: "leave-request-check", title: "Leave Request Check", description: "Leave request field that reads the range as calendar days, working days and leave really used, and flags weekend or holiday ends, a sandwich rule charging days between, half days with no half or a gap, a negative balance and teammates away, with fixes.", category: "Readbacks and calculators", Demo: LeaveRequestCheckDemo },
  { name: "ctc-breakdown-input", title: "CTC Breakdown Input", description: "Splits CTC into fixed pay, variable, ESOPs, joining bonus, gratuity and PF, estimates gratuity and PF in one tap, works out monthly in-hand pay under India's new tax regime with every assumption written down, and flags offers where in-hand is far below the headline.", category: "Readbacks and calculators", Demo: CtcBreakdownInputDemo },
  { name: "guest-count-picker", title: "Guest Count Picker", description: "Guest picker for adults, children and infants that asks each child's age, then flags a child over the age limit (or young enough to be a free infant), infants with no adult, rooms over capacity or out of cots, and a room split that doesn't match the party, with one-tap fixes.", category: "Readbacks and calculators", Demo: GuestCountPickerDemo },
  { name: "salary-input", title: "Salary Input", description: "Salary field that reads \"12 LPA\", \"85k/month\" or \"1.2 Cr\", catches monthly entered as yearly (and back), a bare number meant as lakhs, and an extra zero against the role's range, reads amounts back per month and per year, and offers one-tap fixes.", category: "Readbacks and calculators", Demo: SalaryInputDemo },
  { name: "size-fit-picker", title: "Size Fit Picker", description: "Size picker that converts UK, US, EU and IN sizes live without losing the pick, reads back the shopper's usual size adjusted for brands that run small or large, and catches their usual number clicked in the wrong system with a one-tap fix.", category: "Readbacks and calculators", Demo: SizeFitPickerDemo },
  { name: "unit-input", title: "Unit Input", description: "Measurement input that notices when a value is far more plausible in another unit (70 cm is probably inches, 98.6 °C is °F) or is typed as 5'9\", and offers a one-tap conversion at the right precision or a unit switch.", category: "Readbacks and calculators", Demo: UnitInputDemo },
  { name: "time-confirm", title: "Time Confirm", description: "Time input that asks AM or PM when a time is ambiguous, spells out noon and midnight, catches times a DST change skips (one-tap move to the real time) or repeats (pick which), and shows the moment in other zones with day-shift flags.", category: "Readbacks and calculators", Demo: TimeConfirmDemo },
  { name: "quantity-stepper", title: "Quantity Stepper", description: "Quantity stepper that clamps to min, max and stock with an explanation, rounds to pack sizes, holds big typed jumps for a \"Did you mean 10?\" confirmation, ignores the scroll wheel and accelerates on long-press.", category: "Readbacks and calculators", Demo: QuantityStepperDemo },
  { name: "percent-input", title: "Percent Input", description: "Percent field that catches 0.15 typed for 15%, 0.25 basis points meant as 25, and values outside the allowed range (150% where 100% is the cap), reads the result back in money (15% of ₹2,000 = ₹300) and offers a one-tap fix.", category: "Readbacks and calculators", Demo: PercentInputDemo },
  { name: "range-pair", title: "Range Pair", description: "From/to field pair that catches reversed ends (moving a 28 Dec → 3 Jan end into next year rather than just swapping), equal exclusive ends, and year or extra-zero typos that make a range huge, each with a one-tap fix.", category: "Readbacks and calculators", Demo: RangePairDemo },
  { name: "schedule-readback", title: "Schedule Readback", description: "Cron input that reads the expression back in plain English, lists the next runs in your time zone beside the scheduler's, and catches every-minute stars, day-of-month OR day-of-week, the 31st skipping months and 30 February, with one-tap fixes.", category: "Readbacks and calculators", Demo: ScheduleReadbackDemo },
  { name: "split-allocator", title: "Split Allocator", description: "Split editor that shows what's left as you type, gives the rest to any row in one tap, flags rows on 0, and rounds every automatic split with largest remainder so it sums to the total exactly (100 / 3 → 34, 33, 33).", category: "Readbacks and calculators", Demo: SplitAllocatorDemo },
  { name: "duration-input", title: "Duration Input", description: "Parses 1h30, 90m, 1.5h, 1:30 and 2d 4h into one duration read back in words, catches 1.50 typed for 1 h 50 min, and asks whether 1:30 is h:mm or m:ss when the limits can't decide.", category: "Readbacks and calculators", Demo: DurationInputDemo },
  { name: "billing-period-input", title: "Billing Period Input", description: "Reads a recurring price back per period (₹499/month = ₹5,988/year) and, against a reference price, catches a yearly price in the monthly field, a team total entered per seat and other implausible jumps, each with a one-tap fix.", category: "Readbacks and calculators", Demo: BillingPeriodInputDemo },
  { name: "replace-preview", title: "Replace Preview", description: "Find-and-replace that previews every match in context with a count, names matches inside longer words with a one-tap whole-word fix, preserves case, lets you skip single matches, and undoes the replace.", category: "Readbacks and calculators", Demo: ReplacePreviewDemo },
  { name: "shift-time-input", title: "Shift Time Input", description: "Shift time input that treats 22:00–06:00 as an 8 h overnight shift, asks whether 9:00–5:00 meant 5 PM, questions 0 h, over-long and 26:00-style entries, deducts breaks (catching one typed in hours) and counts real hours across a DST change.", category: "Readbacks and calculators", Demo: ShiftTimeInputDemo },
  { name: "dimension-input", title: "Dimension Input", description: "Labels each side, fills all three from a pasted \"16 x 12 x 8 in\", checks them against what is being measured to catch the wrong unit, an extra digit and sides in the wrong order, and reads the size back in metric and imperial with volume and volumetric weight.", category: "Readbacks and calculators", Demo: DimensionInputDemo },
  { name: "tax-inclusive-input", title: "Tax-Inclusive Input", description: "Price field with an explicit includes/excludes-tax toggle, a net + tax = gross readback, and flags for an \"excludes\" price that divides back to a round number, a mode switch that silently changed the total, and a typo'd rate like 0.18 or 180.", category: "Readbacks and calculators", Demo: TaxInclusiveInputDemo },
  { name: "version-bump", title: "Version Bump", description: "Release picker that reads changes (Conventional Commits or tagged), marks the bump they need, previews each option's version, warns when the pick is too small (or a needless major), and reads back \"1.4.2 → 2.0.0\", handling 0.x, pre-release tags and their ordering.", category: "Readbacks and calculators", Demo: VersionBumpDemo },
  { name: "dose-input", title: "Dose Input", description: "Flags ISMP error-prone dose designations as typed (trailing zeros, missing leading zero, U and IU, µg, cc, a unit flush against the number, uncommaed large numbers), rewrites the dose safely, offers the likely value when 10× outside the usual range and spells it back.", category: "Readbacks and calculators", Demo: DoseInputDemo },
  { name: "leftover-text-check", title: "Leftover Text Check", description: "Text check that flags chatbot chatter and refusals, unfilled placeholders ([product], XX%), TK and TODO markers and paragraphs pasted twice, without false alarms on [1], [sic] or Markdown links, and asks twice before publishing with leftovers.", category: "Parsers and analyzers", Demo: LeftoverTextCheckDemo },
  { name: "ai-citation-check", title: "AI Citation Check", description: "Flags tells of made-up references (DOI prefix not matching the journal, a dash in a DOI, impossible years, leftover oaicite or 【4†source】 markers, unattributed quotes), looks DOIs, cases and links up via a pluggable verify, and marks anything unconfirmed Unverified.", category: "Parsers and analyzers", Demo: AiCitationCheckDemo },
  { name: "k8s-resource-input", title: "K8s Resource Input", description: "Requests/limits fields that read values in plain units and catch CPU 500 meaning 500 cores, 400m memory meaning 0.4 bytes, unit-case slips, a limit under its request, CPU finer than 1m and requests above any node, with fixes, the QoS class and resources: paste.", category: "Parsers and analyzers", Demo: K8sResourceInputDemo },
  { name: "connection-string-input", title: "Connection String Input", description: "Masks the password when not editing, reads back user, host, database and TLS mode, and catches unencoded @ # / % in passwords, localhost in production, missing or weak sslmode, unknown libpq parameters, wrong-database ports, Redis/MongoDB without TLS and .env quoting.", category: "Parsers and analyzers", Demo: ConnectionStringInputDemo },
  { name: "package-name-check", title: "Package Name Check", description: "npm and pip install-command check that flags lookalikes of popular packages (loadsh, crossenv, jeIlyfish), import names that aren't the package (sklearn, cv2, bs4, PIL), built-ins from the registry, unpublishable names, and via lookup, missing or brand-new names.", category: "Parsers and analyzers", Demo: PackageNameCheckDemo },
  { name: "cache-control-input", title: "Cache Control Input", description: "Reads back who stores the response and for how long (browser, CDN via CDN-Cache-Control or Surrogate-Control, other shared caches) and flags per-user pages a CDN can cache, public cookie-setting responses, no-cache mistaken for no-store, unsafe immutable and missing Vary.", category: "Parsers and analyzers", Demo: CacheControlInputDemo },
  { name: "mrz-paste-input", title: "MRZ Paste Input", description: "Passport MRZ field (ICAO 9303 TD3) that validates each check digit and the composite, catches OCR slips like O for 0 and K for <, swapped lines, CRLF and stray spaces, proposes the likeliest fix for a bad digit, flags expired or soon-expiring passports, then fills the fields.", category: "Parsers and analyzers", Demo: MrzPasteInputDemo },
  { name: "curl-pipe-guard", title: "Curl Pipe Guard", description: "Before a curl | sh (or wget, or iwr | iex) one-liner is copied or run, shows the script's real host and flags plain http, raw IPs, shortened links, a host off the product's docs domain, sudo, -k/--insecure and missing checksum or -f; offers safer step-by-step commands.", category: "Parsers and analyzers", Demo: CurlPipeGuardDemo },
  { name: "port-expose-guard", title: "Port Expose Guard", description: "Port mapping check for docker run, compose and Kubernetes Services that says who can reach each port and flags databases on 0.0.0.0 (which Docker opens ahead of ufw), host networking, -P, NodePort or public LoadBalancers, wrong container ports and unquoted 22:22 YAML, with fixes.", category: "Parsers and analyzers", Demo: PortExposeGuardDemo },
  { name: "photo-spec-check", title: "Photo Spec Check", description: "Photo upload check against portal presets (UPSC, SSC, NTA, NEET, US visa) or your spec: real file type, KB, pixels, shape, print size, over-compression, face size and centring, background and colour, with a canvas fix that crops, resizes and re-encodes.", category: "Parsers and analyzers", Demo: PhotoSpecCheckDemo },
  { name: "doc-upload-match", title: "Doc Upload Match", description: "Checks a file against the document asked for (Aadhaar back instead of front, Aadhaar in the PAN slot, a password-locked e-Aadhaar PDF, a multi-page PDF, a tiny, blurry or HEIC photo, a screenshot of a screenshot) using in-browser signals plus an optional classify hook.", category: "Parsers and analyzers", Demo: DocUploadMatchDemo },
  { name: "ai-paste-guard", title: "AI Paste Guard", description: "Reads the HTML clipboard data pasted into an AI prompt box and holds it when it carries invisible text (same-colour, zero-size, display:none, off-screen, comments, alt/title instructions, Unicode tag payloads), shows each hidden passage and can paste only the visible text.", category: "Parsers and analyzers", Demo: AiPasteGuardDemo },
  { name: "ssh-key-input", title: "SSH Key Input", description: "Public-key field that flags a pasted private key loudly (rotate it; extract the public half in one tap), catches DSA and short RSA keys, wrapped or cut-off keys, wrong type prefixes, SSH2 export format and duplicates, and shows the SHA256 fingerprint as ssh-keygen does.", category: "Parsers and analyzers", Demo: SshKeyInputDemo },
  { name: "jwt-inspect", title: "JWT Inspect", description: "Local JWT decoder that never sends the token anywhere and flags alg none, HS vs RS key confusion, an expired token or future nbf (in the reader's zone), millisecond timestamps, a missing aud or iss, very long lifetimes, and secrets or personal data readable in the payload.", category: "Parsers and analyzers", Demo: JwtInspectDemo },
  { name: "cert-paste-check", title: "Cert Paste Check", description: "Identifies certificates, private keys and CSRs in a paste and catches a chain out of order or missing its intermediate, expired or expiring certificates, a hostname the SANs don't cover, self-signed certificates in production and a non-matching key.", category: "Parsers and analyzers", Demo: CertPasteCheckDemo },
  { name: "chmod-input", title: "Chmod Input", description: "Reads any mode (644, 0755, u+x, -rwxr-xr-x) back as rwx and plain words, and flags world-writable files, setuid/setgid, keys and .env files others can read, a writable ~/.ssh or authorized_keys, execute bits on data, 775 typed for 755 and short or decimal modes.", category: "Parsers and analyzers", Demo: ChmodInputDemo },
  { name: "redirect-uri-input", title: "Redirect URI Input", description: "Checks a redirect URI the way an OAuth server does (exact string match), highlighting a differing trailing slash, scheme, case, www or port against the registered list with a one-tap swap, plus localhost in production, wildcards, fragments and stray whitespace.", category: "Parsers and analyzers", Demo: RedirectUriInputDemo },
  { name: "csp-input", title: "CSP Input", description: "Flags 'unsafe-inline' without a nonce, 'unsafe-eval', * / data: / https: in script-src, missing default-src, object-src or base-uri, unquoted keywords, a stray comma that splits the policy, JSONP-hosting allowlisted hosts, typos and report-only traps.", category: "Parsers and analyzers", Demo: CspInputDemo },
  { name: "public-env-guard", title: "Public Env Guard", description: ".env check that lists every NEXT_PUBLIC_, VITE_, REACT_APP_, EXPO_PUBLIC_ or PUBLIC_ variable reaching the browser and flags secret key shapes, Supabase service_role JWTs, passwords in URLs, secret names and high-entropy values, with a server-only rename.", category: "Parsers and analyzers", Demo: PublicEnvGuardDemo },
  { name: "robots-txt-guard", title: "Robots.txt Guard", description: "robots.txt checker that flags Disallow: / for production, staging leftovers, rules blocking CSS/JS Google renders with, relative or wrong-host sitemaps, typos and fields Google ignores, with one-tap fixes and a URL tester naming the deciding line.", category: "Parsers and analyzers", Demo: RobotsTxtGuardDemo },
  { name: "image-tag-input", title: "Image Tag Input", description: "Image reference field showing the implied docker.io/library/ and :latest, flags :latest or no tag in production, moving tags, typo'd or frozen registries, private images that fall back to Docker Hub, malformed digests and arch-specific tags, with fixes such as pinning a digest.", category: "Parsers and analyzers", Demo: ImageTagInputDemo },
  { name: "column-mapper", title: "Column Mapper", description: "Checks a column mapping against sample values: emails in the phone column, first and last names swapped, DD/MM read as MM/DD (with a readback of what a date becomes), the same field mapped twice and required fields left unmapped, each with a one-tap fix.", category: "Parsers and analyzers", Demo: ColumnMapperDemo },
  { name: "boolean-query-input", title: "Boolean Query Input", description: "Shows how the engine groups AND and OR (implied brackets highlighted) and offers the grouping you meant; catches unclosed quotes and brackets, curly quotes, [ ] used as brackets, lowercase and/or and dangling operators, each with a one-tap fix.", category: "Parsers and analyzers", Demo: BooleanQueryInputDemo },
  { name: "cors-origin-input", title: "CORS Origin Input", description: "Catches * with credentials, null, trailing slashes or paths, missing schemes, default ports and http or localhost in production, with one-tap fixes and a tester that names the near miss blocking an origin.", category: "Parsers and analyzers", Demo: CorsOriginInputDemo },
  { name: "webhook-url-input", title: "Webhook URL Input", description: "Webhook URL field that judges the URL for its environment (ngrok, tunnel, localhost or private IP is an error in production, a hint in test), flags staging hosts, plain http and missing paths, and diffs against the last saved URL to catch www or trailing-slash-only changes.", category: "Parsers and analyzers", Demo: WebhookUrlInputDemo },
  { name: "list-paste", title: "List Paste", description: "Paste box that splits on lines, commas, semicolons and tabs (keeping \"Shah, Priya\" <…> whole), counts valid, duplicate and invalid items with the line and reason for each, and removes the bad ones in one undoable tap. Validator is pluggable.", category: "Parsers and analyzers", Demo: ListPasteDemo },
  { name: "env-paste", title: "Env Paste", description: "Catches .env slips loaders accept silently (stray or curly quotes, padded values, a ' #' that cuts a value short, duplicate keys, bad key names, empty values, test keys in production) by showing a parsed table of what the app will read, with one-tap fixes.", category: "Parsers and analyzers", Demo: EnvPasteDemo },
  { name: "json-field", title: "JSON Field", description: "JSON text field that validates as you type, shows a caret at the exact line and column, and repairs trailing commas, single or smart quotes, unquoted keys, comments, Python literals (True/None), missing commas and unclosed braces with a token-aware fix. Includes Format.", category: "Parsers and analyzers", Demo: JsonFieldDemo },
  { name: "regex-field", title: "Regex Field", description: "Regex input with static checks (unescaped dot, missing ^…$, greedy .*, nested quantifiers like (a+)+), plain-English hints, one-tap fixes, and live test strings matched in a time-capped Web Worker so a runaway pattern can't freeze the page.", category: "Parsers and analyzers", Demo: RegexFieldDemo },
  { name: "cidr-input", title: "CIDR Input", description: "Reads an IPv4 or IPv6 CIDR back as its exact range and address count, catches host bits set (offering both the network and single-host readings), and warns on 0.0.0.0/0, a missing prefix, leading zeros and overlaps with existing ranges.", category: "Parsers and analyzers", Demo: CidrInputDemo },
  { name: "version-range-input", title: "Version Range Input", description: "npm-style semver range input that reads ranges back in plain English, marks which published versions match and which installs, and warns about ^0.x lock-in, a hyphen without spaces, commas used for AND and ranges that match nothing.", category: "Parsers and analyzers", Demo: VersionRangeInputDemo },
  { name: "glob-input", title: "Glob Input", description: "Glob field that matches the pattern live against the files you pass, flags no-match and match-everything patterns, the * vs ** mix-up that skips subfolders, ** glued to a name, ./ and backslashes, with one-tap fixes. Dependency-free matcher with {a,b} expansion.", category: "Parsers and analyzers", Demo: GlobInputDemo },
  { name: "i18n-string-field", title: "i18n String Field", description: "Translation field that compares the text with its source: dropped or renamed placeholders ({count}, %s, {{name}}, <b>…</b>), unclosed tags, ICU plural forms the target language needs per CLDR, rendered length against a UI budget, and untranslated pastes. One-tap fixes.", category: "Parsers and analyzers", Demo: I18nStringFieldDemo },
  { name: "sql-guard", title: "SQL Guard", description: "SQL box with a small tokenizer (comments and strings ignored) that flags UPDATE/DELETE without WHERE, a commented-out WHERE, always-true conditions, DROP and TRUNCATE, asks before writes on production, shows estimated rows and requires typing the table name.", category: "Parsers and analyzers", Demo: SqlGuardDemo },
  { name: "markdown-check", title: "Markdown Check", description: "Markdown field that catches unclosed ** or backticks, [text] (url) with a space, empty or space-broken links, #Title with no space and raw HTML the sanitizer strips, previews each spot as it will render, and offers a one-tap fix.", category: "Parsers and analyzers", Demo: MarkdownCheckDemo },
  { name: "yaml-field", title: "YAML Field", description: "YAML editor that flags values that load without error but change meaning (NO/yes/on/off as booleans, 1.10 as 1.1, 0755 as octal, 22:22 as base-60), duplicate keys, tabs and misaligned indentation, with line, column, the parsed value and one-tap fixes.", category: "Parsers and analyzers", Demo: YamlFieldDemo },
  { name: "webhook-test", title: "Webhook Test", description: "Webhook URL field that flags localhost and private IPs, plain http, a missing path and tunnel URLs, then judges a test delivery like the sender: redirects fail (one-tap switch to the final URL), slow replies near the timeout and 200 login pages are caught.", category: "Parsers and analyzers", Demo: WebhookTestDemo },
  { name: "utm-check", title: "UTM Check", description: "UTM link checker that catches mixed case and spaces, source and medium swapped, a medium GA4's default channel rules file as organic or Unassigned, misspelled keys, a second \"?\", tags after \"#\" and tags on internal links, and reads back the GA4 channel.", category: "Parsers and analyzers", Demo: UtmCheckDemo },
  { name: "reorder-readback", title: "Reorder Readback", description: "Sortable list that announces each move with its meaning (\"Moved Razorpay from 3rd to 1st. It's now tried first.\") and Undo. Drags only from the grip, refuses to displace pinned rows, marks rows moved since save, and offers click, arrow and keyboard moves.", category: "Forms and saving", Demo: ReorderReadbackDemo },
  { name: "nominee-check", title: "Nominee Check", description: "Nomination form check for bank deposits, lockers and demat/MF holdings: shares not adding to 100%, nominees past the limit (4 bank, 3 demat), splits on a locker, missing relationship or minor's date of birth, minors with no adult, duplicates and no nominee, with a plain readback.", category: "Forms and saving", Demo: NomineeCheckDemo },
  { name: "passport-validity-check", title: "Passport Validity Check", description: "Passport check against the destination's rule (6 months, Schengen's 3 months after leaving and 10 years since issue, blank pages) that names the exact date it must last until and offers the latest return that would pass. Default rules carry sources and can be replaced.", category: "Forms and saving", Demo: PassportValidityCheckDemo },
  { name: "seat-gap-check", title: "Seat Gap Check", description: "Seat-map check for group bookings: a party split across the row, a single empty seat left behind (which many venues refuse) and a child seated away from every adult, with problem seats marked and a one-tap move to the nearest block that fits.", category: "Forms and saving", Demo: SeatGapCheckDemo },
  { name: "formula-overwrite-guard", title: "Formula Overwrite Guard", description: "Previews in place which cells a paste would change and how, leaves out a heading row the copy dragged along, and offers to paste values only into empty and non-formula cells; safe pastes go straight in with Undo.", category: "Forms and saving", Demo: FormulaOverwriteGuardDemo },
  { name: "passkey-name-prompt", title: "Passkey Name Prompt", description: "Post-creation passkey naming prompt that prefills a distinct name from the AAGUID (iCloud Keychain, 1Password) or the device (\"Mac · Chrome\", phone, security key), numbers it when taken, blocks empty and duplicate names, nudges away from generic ones, and says whether it syncs.", category: "Forms and saving", Demo: PasskeyNamePromptDemo },
  { name: "irreversible-diff-badge", title: "Irreversible Diff Badge", description: "Chip for permanent fields that turns amber once edited, plus a pre-save readback listing only the permanent fields that changed (from → to) with consequences and one-tap Revert, behind a confirmation that resets whenever that list changes.", category: "Forms and saving", Demo: IrreversibleDiffBadgeDemo },
  { name: "stale-attachment-check", title: "Stale Attachment Check", description: "Attachment check against nearby files: a newer save of the same document, names saying draft, old, copy or (1), Office lock files and files dated before the subject's date, with a one-tap swap to the newer file and Undo.", category: "Forms and saving", Demo: StaleAttachmentCheckDemo },
  { name: "dependency-license-check", title: "Dependency License Check", description: "Reads each SPDX expression against your policy (GPL or AGPL in closed source, no or unknown license, source-available terms in a hosted product, deny lists) and catches relicenses between versions with a one-tap \"Stay on\" the last version under the old license.", category: "Forms and saving", Demo: DependencyLicenseCheckDemo },
  { name: "heading-outline", title: "Heading Outline", description: "Live heading outline for a Markdown draft or DOM region. Flags skipped levels (shown as dashed ghost rows), extra or missing H1s, empty headings, bold text posing as a heading and overlong headings, with a one-tap level fix and rows that jump to the heading.", category: "Forms and saving", Demo: HeadingOutlineDemo },
  { name: "link-text-check", title: "Link Text Check", description: "Link text check for Markdown or a live DOM region that flags \"click here\" and \"read more\", URLs as link text, empty links and the same text pointing to different places, with a rewrite that lifts the sentence's own words into the link and a view of the links list as read out.", category: "Forms and saving", Demo: LinkTextCheckDemo },
  { name: "reading-level", title: "Reading Level", description: "Live Flesch-Kincaid grade against a target. Tints the hardest sentences in place (only when long and dense), with the reason and a jump to each, and offers one-tap plain-word swaps (\"utilize\" → \"use\").", category: "Forms and saving", Demo: ReadingLevelDemo },
  { name: "backup-codes", title: "Backup Codes", description: "Continue unlocks only after the codes are downloaded, printed or copied (or all three with require=\"all\"); then one code must be typed back, with paste refused and look-alike characters forgiven, to show the saved copy is readable.", category: "Forms and saving", Demo: BackupCodesDemo },
  { name: "recovery-check", title: "Recovery Check", description: "Account-recovery checkup. Flags recovery email or phone not confirmed in months, no backup method, a password-only account, one phone acting as both second factor and recovery, and low backup codes, each with a fix callback.", category: "Forms and saving", Demo: RecoveryCheckDemo },
  { name: "unsaved-changes-bar", title: "Unsaved Changes Bar", description: "Unsaved-changes bar that names every dirty field (with per-field revert), guards the tab close, saves on Ctrl/⌘+S and asks twice before Discard; editing a field back to its saved value makes it clean again.", category: "Forms and saving", Demo: UnsavedChangesBarDemo },
  { name: "save-status", title: "Save Status", description: "Autosave status with an aging \"Saved · 2 min ago\", an honest offline state and Retry on error, plus a debounced useAutosave hook that runs one save at a time and always saves the newest value last.", category: "Forms and saving", Demo: SaveStatusDemo },
  { name: "error-summary", title: "Error Summary", description: "A summary that takes focus on submit, links each error to its field, and ticks items off live as they are fixed, plus a useFormErrors() hook.", category: "Forms and saving", Demo: ErrorSummaryDemo },
  { name: "form-progress", title: "Form Progress", description: "Watches a form and counts the required fields still empty or invalid, with a Next missing button that moves focus to the next one.", category: "Forms and saving", Demo: FormProgressDemo },
  { name: "preflight-checklist", title: "Preflight Checklist", description: "Checklist that locks an action until auto and manual checks pass, names the blockers, resets manual ticks and re-runs checks when the revision changes, and re-verifies right before the action runs.", category: "Forms and saving", Demo: PreflightChecklistDemo },
  { name: "attachment-nudge", title: "Attachment Nudge", description: "Spots attachment phrases in English, Hindi and Hinglish (\"PFA\", \"attach kar diya\"), ignoring quoted replies, negations, future mentions and shared cloud links, and asks inline to Attach or Send anyway.", category: "Forms and saving", Demo: AttachmentNudgeDemo },
  { name: "file-guard", title: "File Guard", description: "Checks size, type, count, empty files and duplicates, and reads each file's first bytes to catch a renamed extension, with a one-tap rename fix.", category: "Forms and saving", Demo: FileGuardDemo },
  { name: "draft-restore", title: "Draft Restore", description: "Autosaves to localStorage and, on reopen, offers the draft with a field-by-field preview that keeps any value the server changed since, unless you tick it. Drafts expire after 7 days by default.", category: "Forms and saving", Demo: DraftRestoreDemo },
  { name: "tab-collision", title: "Tab Collision", description: "Single-editor lock across tabs: one tab edits (BroadcastChannel, with a localStorage storage-event fallback), the others become read-only until someone picks \"Use this tab\", with a confirm when the other tab has unsaved changes.", category: "Forms and saving", Demo: TabCollisionDemo },
  { name: "review-step", title: "Review Step", description: "Review page for wizards: every answer by step with named Edit links, empty optional fields and values changed since last time flagged, missing required answers blocking submit, and one deliberate submit that ignores carried-over clicks and disables while pending.", category: "Forms and saving", Demo: ReviewStepDemo },
  { name: "dependent-reset", title: "Dependent Reset", description: "A hook clears only what a parent change made invalid (pruning just the add-ons a new plan lacks), and a notice names each lost value, highlights those fields and offers Undo.", category: "Forms and saving", Demo: DependentResetDemo },
  { name: "version-scrubber", title: "Version Scrubber", description: "Version timeline with the current version pinned, a word diff of exactly what a restore would change, and a second confirm step that counts words lost and gained and names changed numbers.", category: "Forms and saving", Demo: VersionScrubberDemo },
  { name: "autofill-check", title: "Autofill Check", description: "Detects autofill (the :autofill animationstart hook plus a no-typing batch heuristic), outlines and lists filled fields for review, flags an email in Name or a value that differs from the account with a one-tap fix, and holds the first submit.", category: "Forms and saving", Demo: AutofillCheckDemo },
  { name: "field-history", title: "Field History", description: "A trigger beside the label flags a recent change by someone else and opens \"Was ₹500 until Priya changed it yesterday\" with a one-tap revert of that field alone, says what the revert replaces (including your unsaved edit) and lets you undo it.", category: "Forms and saving", Demo: FieldHistoryDemo },
  { name: "terms-changes", title: "Terms Changes", description: "Terms re-acceptance with a summary and exact word diff since the accepted version, changed numbers called out, Accept locked until every change has stayed on screen long enough to read (an early tap jumps to the next unread one), and a consent record with both versions.", category: "Forms and saving", Demo: TermsChangesDemo },
  { name: "hidden-field-guard", title: "Hidden Field Guard", description: "Banner for a hidden conditional section that names the fields still holding values and says whether they will be submitted or dropped, with Keep, Clear (through real input events so React state follows) and Undo.", category: "Forms and saving", Demo: HiddenFieldGuardDemo },
  { name: "upload-wait", title: "Upload Wait", description: "Submit button for forms with uploads: pressing submit mid-upload validates and queues the send, the button fills with combined progress (\"Waiting for 2 uploads…\"), it submits by itself when they finish, a failed upload pauses it until retried, and leaving asks first.", category: "Forms and saving", Demo: UploadWaitDemo },
  { name: "consent-group", title: "Consent Group", description: "Boxes are never pre-ticked, required terms sit apart from optional purposes, Accept all spells out what it will tick first, one sentence reads back the choice, and each change produces a record with time, method, text version and a fingerprint of the wording.", category: "Forms and saving", Demo: ConsentGroupDemo },
  { name: "dob-input", title: "DOB Input", description: "Reads the date and age back as you type and catches this year typed by habit (age 0), future dates, implausible ages, a day typed into the month box, pasted dates that read two ways and under-age sign-ups, with a fix and the date someone becomes eligible.", category: "Forms and saving", Demo: DobInputDemo },
  { name: "recurrence-scope", title: "Recurrence Scope", description: "This one / This and following / All picker for recurring events that reads back the dates each choice changes, with counts and past dates called out, and warns by date and field before overwriting occurrences that were edited on their own.", category: "Forms and saving", Demo: RecurrenceScopeDemo },
  { name: "tree-select-readback", title: "Tree Select Readback", description: "Nested checkbox tree that reads the choice back in plain words (\"All of Marketing except Paid ads; 3 of 12 in Sales\"), tells a whole-group tick apart from ticking every item, and warns that a whole-group tick includes items added later, with a one-tap pin to today's items.", category: "Forms and saving", Demo: TreeSelectReadbackDemo },
  { name: "repeat-rows", title: "Repeat Rows", description: "Add-another rows (line items, guests) with min and max limits, Undo after a remove, duplicate rows flagged with a one-tap remove, blank rows called out before submit, Enter that adds a row instead of submitting, and focus that lands on the right field.", category: "Forms and saving", Demo: RepeatRowsDemo },
  { name: "step-invalidation", title: "Step Invalidation", description: "Wizard helper that says exactly what a change to an earlier answer clears (\"Changing plan to Basic clears Region on step 3…\") before applying it, marks affected steps, reviews only them and holds Finish until they're checked; changing back restores what was removed.", category: "Forms and saving", Demo: StepInvalidationDemo },
  { name: "import-preview", title: "Import Preview", description: "Import preview that finds the real heading row, maps columns by heading and by values with a confidence, holds the import while a required field is unmapped, and lists every skipped line with its line number and reason before a plain \"Import 412 · skip 7\".", category: "Forms and saving", Demo: ImportPreviewDemo },
  { name: "crop-guard", title: "Crop Guard", description: "Checks pluggable face and text boxes against the crop, the profile circle and Story safe zones, offers a one-tap fit that moves the crop as little as possible, and previews it at the small size people actually see.", category: "Forms and saving", Demo: CropGuardDemo },
  { name: "stay-length", title: "Stay Length", description: "Date range readback (\"Mon 2 Nov – Sun 8 Nov · 6 nights, 7 days\") that flags an end before the start, nights confused with days, a check-out that may really be the last night, and weekends or holidays that change how much leave it costs, each with a one-tap fix.", category: "Forms and saving", Demo: StayLengthDemo },
  { name: "event-overlap", title: "Event Overlap", description: "Lists clashes (overlaps, back-to-back with no break, too little travel time between places, busy all-day events, other-zone events in their own time) on a small timeline, and moves the event to the nearest slot that keeps your buffer and travel time, with Undo.", category: "Forms and saving", Demo: EventOverlapDemo },
  { name: "unanswered-check", title: "Unanswered Check", description: "Pre-submit check for tests and surveys: required and optional blanks, partly answered and flagged questions as numbered jump links, time left and per-question pace, a second click for blanks, a hard stop for required survey questions and a submit that waits for saves.", category: "Forms and saving", Demo: UnansweredCheckDemo },
  { name: "cutoff-picker", title: "Cutoff Picker", description: "Counts down to the cutoff in store time with the shopper's time beside it, names skipped holidays and closed days, says when the store's date differs, and never moves a chosen date silently: a passed cutoff is announced with the new earliest date one tap away.", category: "Forms and saving", Demo: CutoffPickerDemo },
  { name: "trip-date-chain", title: "Trip Date Chain", description: "Night-by-night strip of stays under flights that catches a small-hours landing with the room booked from that date, nights paid before a +1 arrival, gap nights, double-booked nights and a room kept past a small-hours departure, with one-tap fixes and Undo.", category: "Context and awareness", Demo: TripDateChainDemo },
  { name: "meeting-time-spread", title: "Meeting Time Spread", description: "Meeting time slider with each attendee's day underneath (night, before or after work, weekend, day ahead or behind, DST weeks via the tz database) that suggests the kindest slot: nobody at night, then fewest out of hours, then rotating away from recent sufferers.", category: "Context and awareness", Demo: MeetingTimeSpreadDemo },
  { name: "bnpl-schedule-check", title: "BNPL Schedule Check", description: "Draws each payment on a calendar beside other plans and paydays, flags a card that expires before a payment, payments just before payday and plans stacking in one week, offers one-tap fixes, shows the late fee in money and asks for a second press while the card problem stands.", category: "Context and awareness", Demo: BnplScheduleCheckDemo },
  { name: "transit-visa-check", title: "Transit Visa Check", description: "Layover check against starter airport transit visa lists (UK, Germany, France, Netherlands; US has no airside transit) and border-entry traps (self-transfer, onward Schengen flight, UK to Ireland, leaving the airport), with exempting documents and official links.", category: "Context and awareness", Demo: TransitVisaCheckDemo },
  { name: "llm-cost-estimate", title: "LLM Cost Estimate", description: "Pre-run cost panel that estimates input/output tokens and cost from your dated price table, shows the worst case without max_tokens, catches context-window overflows, runs far bigger than the last and premium models on bulk jobs, and shows Batch API savings.", category: "Context and awareness", Demo: LlmCostEstimateDemo },
  { name: "kube-context-guard", title: "Kube Context Guard", description: "kubectl/helm field that shows the context, cluster and namespace a command will really use, flags production, the default namespace, a manifest namespace that disagrees with -n and a switched context, and asks for the context name before production changes.", category: "Context and awareness", Demo: KubeContextGuardDemo },
  { name: "security-event-log", title: "Security Event Log", description: "Security activity log that highlights risky changes from other devices, groups a burst (new device, 2-step off, new recovery email) as a likely takeover, and offers \"This wasn't me\" with each remedy as an untickable checkbox. Times follow the account's zone.", category: "Context and awareness", Demo: SecurityEventLogDemo },
  { name: "dst-shift-notice", title: "DST Shift Notice", description: "Lists each attendee's affected dates with the new local time when daylight saving changes on different dates (US and EU weeks apart, India never), flags moves outside working hours, and offers to fix the series to the organiser's zone or UTC with a count of who moves.", category: "Context and awareness", Demo: DstShiftNoticeDemo },
  { name: "environment-badge", title: "Environment Badge", description: "Marks the page, tab title (kept through navigation) and favicon with PRODUCTION, STAGING or DEV (production hatched in red), reads names like \"eu-prod-2\" word by word, never calls an unknown environment safe, and includes a hook that asks for confirmation only in production.", category: "Context and awareness", Demo: EnvironmentBadgeDemo },
  { name: "acting-as-banner", title: "Acting As Banner", description: "Shows a sticky \"You're acting as…\" bar with who is really signed in, a countdown to when impersonation ends and a switch-back action, plus an org chip that makes each destructive button say where it acts.", category: "Context and awareness", Demo: ActingAsBannerDemo },
  { name: "offline-banner", title: "Offline Banner", description: "Connection banner that counts queued changes while offline, stays up after reconnecting until the queue has actually synced, offers Retry if the sync fails, and can warn before leaving with unsynced changes.", category: "Context and awareness", Demo: OfflineBannerDemo },
  { name: "stale-data-notice", title: "Stale Data Notice", description: "Banner that appears when a tab comes back after a while (default 5 min away) or the data passes its max age (default 10 min), says how old it is and why that matters, and offers a one-tap refresh.", category: "Context and awareness", Demo: StaleDataNoticeDemo },
  { name: "conflict-banner", title: "Conflict Banner", description: "Names who changed the record and when, shows a word diff, and before \"Keep mine\" confirms how many of their words it would replace, until you've compared.", category: "Context and awareness", Demo: ConflictBannerDemo },
  { name: "session-timeout", title: "Session Timeout", description: "Idle-timeout warning dialog with a countdown and a draining ring that turns red in the last 10 seconds, a Stay signed in action that extends the session through your callback, cross-tab activity sync and calm screen-reader announcements.", category: "Context and awareness", Demo: SessionTimeoutDemo },
  { name: "do-not-close", title: "Do Not Close", description: "Adds a close warning and a marked tab title while work runs, shows a rolling-rate time-left estimate, says \"Safe to close\" when done and offers Retry when it fails.", category: "Context and awareness", Demo: DoNotCloseDemo },
  { name: "timezone-mismatch", title: "Timezone Mismatch", description: "Banner shown when the device zone differs from the account zone: both clocks side by side, a one-time choice to use the device zone, a confirmation that keeps focus, remembered per pair of zones, comparing real clock changes so briefly drifting zones still count.", category: "Context and awareness", Demo: TimezoneMismatchDemo },
  { name: "update-available", title: "Update Available", description: "New-deploy banner that polls a version endpoint (or takes a prop), explains what a refresh does, never refreshes while there are unsaved changes (offering \"Refresh after I save\"), and lets \"Later\" skip only that build.", category: "Context and awareness", Demo: UpdateAvailableDemo },
  { name: "revision-banner", title: "Revision Banner", description: "Banner for viewing an old revision: the content sits in a read-only striped frame that explains blocked edits, and \"Restore this version\" confirms which latest version it replaces and how many words change.", category: "Context and awareness", Demo: RevisionBannerDemo },
  { name: "filter-notice", title: "Filter Notice", description: "Says how many items active filters hide, shows each filter as a removable chip with how many items it hides on its own, and warns when selected items are hidden.", category: "Context and awareness", Demo: FilterNoticeDemo },
  { name: "disabled-reason", title: "Disabled Reason", description: "Keeps the control focusable with aria-disabled and explains on hover, focus or tap what blocks it, in a portalled panel no toolbar can clip, with a jump to each fix, a shake when a blocked press lands and cleared blockers sliding away.", category: "Context and awareness", Demo: DisabledReasonDemo },
  { name: "quota-forecast", title: "Quota Forecast", description: "Usage meter that projects the current rate to the reset (\"At this pace you'll run out Thu 22 Oct\"), turns amber or red on that forecast rather than on raw usage, marks the even-pace point, and says what happens at the limit.", category: "Context and awareness", Demo: QuotaForecastDemo },
  { name: "resume-marker", title: "Resume Marker", description: "Saves the item a reader rested on (after a short delay) to localStorage, marks it \"You were here\" on return, and offers a jump there and back instead of scrolling the page by itself.", category: "Context and awareness", Demo: ResumeMarkerDemo },
  { name: "new-content-pill", title: "New Content Pill", description: "Live feed wrapper that holds new arrivals behind a \"5 new posts\" pill that inserts and scrolls up on tap, inserting directly only when the reader is at the top and not mid-press. Works in its own scroll box or with scrollTarget=\"window\".", category: "Context and awareness", Demo: NewContentPillDemo },
  { name: "presence-lock", title: "Presence Lock", description: "Presence UI that shows who is editing what (\"Priya is editing Price\"), softly locks that field in their colour with an \"Edit anyway\" that warns once, never locks someone already typing, and releases locks held by idle people. Transport-agnostic.", category: "Context and awareness", Demo: PresenceLockDemo },
  { name: "unsent-marker", title: "Unsent Marker", description: "Left-behind draft shown as a dashed \"Not sent · Priya hasn't received it\" bubble in the thread where the reply would be, with Send, Edit and a two-tap Discard, plus a \"Not sent:\" preview for conversation lists.", category: "Context and awareness", Demo: UnsentMarkerDemo },
  { name: "presenter-mode", title: "Presenter Mode", description: "Presenting mode where values wrapped in <Sensitive> are removed from the page (not blurred) behind fixed-length masks, a visible bar shows the mode is on, a deliberate hold peeks one value, and starting a screen share in this tab suggests turning it on.", category: "Context and awareness", Demo: PresenterModeDemo },
  { name: "locale-notice", title: "Locale Notice", description: "Shows a value as you write it and as the reader's locale writes it, says what they would take it to mean (\"In Germany, 1,000 reads as 1\"), offers a form neither side can flip, and catches numbers typed with the other convention's decimal mark (\"1,5\" becoming 15).", category: "Context and awareness", Demo: LocaleNoticeDemo },
  { name: "progress-heartbeat", title: "Progress Heartbeat", description: "Progress bar that separates working from stalled (no heartbeat for N seconds: \"No progress for 40s\" with Retry), alive-but-not-advancing from silence, shows a time-left range that widens instead of a jumpy countdown, and holds at 99% until the job reports done.", category: "Context and awareness", Demo: ProgressHeartbeatDemo },
  { name: "account-switch-guard", title: "Account Switch Guard", description: "When several accounts are signed in, names who the action runs as and who it is not (\"Posting as Acme Corp, not Tushar\"), and catches a switch made in another tab so the button names the page's account instead of silently acting as the new one.", category: "Context and awareness", Demo: AccountSwitchGuardDemo },
  { name: "maintenance-window", title: "Maintenance Window", description: "Banner for planned downtime in the reader's time zone with a countdown that sharpens as it nears, a start button that warns when a long job would run into the window, and, during the window, a notice to keep unsaved edits plus a reload warning.", category: "Context and awareness", Demo: MaintenanceWindowDemo },
  { name: "permission-pre-ask", title: "Permission Pre-Ask", description: "In-page pre-ask for browser permissions that explains why before calling the real API, tells a closed prompt from a block, shows this browser's exact re-enable steps, and flips to on by itself once the user allows it.", category: "Context and awareness", Demo: PermissionPreAskDemo },
  { name: "clock-skew", title: "Clock Skew", description: "Compares the device clock with server time (Date header or prop), says by how much and what breaks (authenticator codes, \"expires in\" timers, secure sites), corrects the countdowns inside it, and clears the warning once the clock is fixed.", category: "Context and awareness", Demo: ClockSkewDemo },
  { name: "private-mode-notice", title: "Private Mode Notice", description: "Notice for private windows, blocked site data or a full quota, based on a real write test before any guess, that offers to export unsaved work and can warn before the tab closes.", category: "Context and awareness", Demo: PrivateModeNoticeDemo },
  { name: "experimental-badge", title: "Experimental Badge", description: "The badge opens a plain list of concrete risks (work may be lost, things may change or disappear), a feedback link and a one-tap switch back to the stable version that says what happens to their work.", category: "Context and awareness", Demo: ExperimentalBadgeDemo },
  { name: "retry-after", title: "Retry After", description: "Action button that, on 429/503, reads Retry-After (seconds or HTTP-date) and RateLimit headers, explains which limit was hit and when it resets, counts down, ignores impatient clicks and retries automatically with jitter while the user's input stays put.", category: "Context and awareness", Demo: RetryAfterDemo },
  { name: "low-battery-guard", title: "Low Battery Guard", description: "Pre-task banner that compares battery runway (to a safety reserve, from the Battery Status API or a measured drain rate) with the task's length, shows where the battery would cut it off, and offers \"Start when plugged in\". Stays silent when the task will finish anyway.", category: "Context and awareness", Demo: LowBatteryGuardDemo },
  { name: "data-cost-notice", title: "Data Cost Notice", description: "On Data Saver, mobile data or a slow connection (Network Information API, or a Save-Data hint you pass) shows the size and an honest rough time, offers a lighter version with what it saves, or waits for Wi-Fi and then starts by itself.", category: "Context and awareness", Demo: DataCostNoticeDemo },
  { name: "sunset-notice", title: "Sunset Notice", description: "Reads Sunset (RFC 8594) and Deprecation (RFC 9745) headers and their Link relations, lists what stops working, shows when in the reader's zone (flagging a different day than the UTC date), turns amber then red, and snoozes only until the next 30/7/1-day mark.", category: "Context and awareness", Demo: SunsetNoticeDemo },
  { name: "print-guard", title: "Print Guard", description: "Pre-print check that finds light-on-dark text the browser drops, collapsed sections, tables wider than the page, scroll boxes that print only what's visible and links without addresses, with print-only fixes; since Ctrl+P can't be stopped, autoFix applies them too.", category: "Context and awareness", Demo: PrintGuardDemo },
  { name: "bcc-guard", title: "Bcc Guard", description: "Previews the To line as one recipient sees it, counts the names, private addresses and companies exposed, flags lists where membership is itself sensitive (\"HIV\", \"arrears\"), moves outside recipients to Bcc in one tap with Undo, and asks for a second press to send.", category: "Sharing, sending and paying", Demo: BccGuardDemo },
  { name: "hidden-content-check", title: "Hidden Content Check", description: "Pre-share check for Office files that reads the file locally with no dependencies and lists hidden and very hidden sheets, hidden rows and columns, tracked deletions, hidden text, comments, speaker notes, hidden slides, embedded workbooks, internal-drive links and author details.", category: "Sharing, sending and paying", Demo: HiddenContentCheckDemo },
  { name: "prompt-data-guard", title: "Prompt Data Guard", description: "AI chat composer guard that says before send what goes where (\"248 customer rows and a CONFIDENTIAL doc will go to OpenAI\"), counting table rows, name columns, emails, phones, cards, Aadhaar, PAN and API keys in text and attachments, and can send with stand-ins.", category: "Sharing, sending and paying", Demo: PromptDataGuardDemo },
  { name: "bill-split-check", title: "Bill Split Check", description: "Checks an item-by-item split against the receipt and catches unclaimed items, tax counted twice, a tip on top of a service charge, a total that doesn't match and what an equal split costs the lightest eater, each with a fix and Undo. Shares are rounded so they always add up.", category: "Sharing, sending and paying", Demo: BillSplitCheckDemo },
  { name: "callback-number-check", title: "Callback Number Check", description: "Reads a callback number's country and line type with libphonenumber and flags +1 Caribbean codes posing as US area codes, one-ring calls from abroad, premium-rate and shared-cost lines, foreign toll-free, unassigned ranges and 'bank' numbers missing from its list.", category: "Sharing, sending and paying", Demo: CallbackNumberCheckDemo },
  { name: "quote-lock", title: "Quote Lock", description: "Held-quote panel that drains as the hold ends, fetches a fresh quote (skew-safe with validFor), rolls old to new with the difference called out, turns a worse-than-tolerance price into an explicit Accept, re-quotes a late Pay, and ignores stale responses and double presses.", category: "Sharing, sending and paying", Demo: QuoteLockDemo },
  { name: "calendar-external-guest-guard", title: "Calendar External Guest Guard", description: "Names guests outside your domains (and a colleague's personal Gmail used for their work address), then lists what they get under Google Calendar defaults: internal agenda lines, file names, open-link files, the guest list, edit rights. Fixes, Undo, second press to send.", category: "Sharing, sending and paying", Demo: CalendarExternalGuestGuardDemo },
  { name: "chat-audience-check", title: "Chat Audience Check", description: "Flags members whose name differs from how you saved them, unidentifiable names, people who joined after your last message and outsiders. Quiet for ordinary messages; for sensitive text it lists them with Remove, View profile and \"I know them\" and needs a second press.", category: "Sharing, sending and paying", Demo: ChatAudienceCheckDemo },
  { name: "out-of-office-check", title: "Out of Office Check", description: "Auto-reply check for Gmail or Outlook that reads back when replies go out and who gets which text, compares dates with the return date in the message, and flags replying on your return day, stopping early, no end date, last time's date, and outside replies that overshare.", category: "Sharing, sending and paying", Demo: OutOfOfficeCheckDemo },
  { name: "retract-window", title: "Retract Window", description: "Under a sent message: how long Edit and Unsend stay open on that platform (iMessage, WhatsApp, Slack presets or your own), a draining bar, who already read it and whose app keeps the original, Delete for me kept apart, and a correction once windows close.", category: "Sharing, sending and paying", Demo: RetractWindowDemo },
  { name: "card-bill-pay", title: "Card Bill Pay", description: "Before Pay, explains what the amount does: anything short of the total loses the interest-free period on the whole bill and on new spends, the minimum is turned into years and interest, and below the minimum or past the 3-day grace it shows the late fee and credit-bureau report.", category: "Sharing, sending and paying", Demo: CardBillPayDemo },
  { name: "otp-share-guard", title: "OTP Share Guard", description: "OTP display that says what the code approves (\"approves a ₹24,999 payment to Croma\") and, during a call or screen share or when it isn't what the user started, shows a never-share warning with hold-to-reveal, delayed Copy, a code hidden while sharing and \"Not me\".", category: "Sharing, sending and paying", Demo: OtpShareGuardDemo },
  { name: "bank-transfer-timing", title: "Bank Transfer Timing", description: "Reads back when money arrives on the chosen rail (IMPS/UPI instantly, the next half-hourly NEFT batch plus up to 2 hours, RTGS within 30 minutes) and catches RTGS under ₹2 lakh, IMPS over ₹5 lakh, UPI over its category cap, bank limits and new-payee caps.", category: "Sharing, sending and paying", Demo: BankTransferTimingDemo },
  { name: "gift-card-scam-guard", title: "Gift Card Scam Guard", description: "Gift card checkout check. Spots scam patterns (large total, several cards, notes about a boss, tax, police, refunds or tech support, sending codes, a first order), says no real company takes gift-card payment, and asks one question; \"someone asked me to\" ends at a stop screen.", category: "Sharing, sending and paying", Demo: GiftCardScamGuardDemo },
  { name: "commit-secret-guard", title: "Commit Secret Guard", description: "Scans only added diff lines for provider keys, private keys, passwords in URLs, hard-coded secrets and high-entropy strings, flags .env and key files, skips test fixtures by pattern (except live key formats), and offers per-finding fixes, warning to rotate if already pushed.", category: "Sharing, sending and paying", Demo: CommitSecretGuardDemo },
  { name: "publish-preview", title: "Publish Preview", description: "npm publish preview from `npm pack --dry-run --json` that flags .env files and keys, source maps, tests, repo config, large files, entry points missing from the build, an already-published version, private: true and no files allowlist, with fixes.", category: "Sharing, sending and paying", Demo: PublishPreviewDemo },
  { name: "upi-autopay-review", title: "UPI AutoPay Review", description: "Pre-approval review of a UPI AutoPay mandate: cap, schedule, validity and merchant read back against the plan, flagging a cap far above the price, \"as presented\" schedules, no end date, the wrong merchant and debits above the PIN-free limit, with one-tap fixes.", category: "Sharing, sending and paying", Demo: UpiAutopayReviewDemo },
  { name: "upi-collect-guard", title: "UPI Collect Guard", description: "Collect-request screen that states \"You pay ₹4,999 to…\", asks whether the user expects to receive money (a yes becomes a decline-only stop), and flags refund, prize, OLX-buyer and KYC wording, person-to-person collects, unknown requesters and small test amounts before the PIN.", category: "Sharing, sending and paying", Demo: UpiCollectGuardDemo },
  { name: "tds-invoice-total", title: "TDS Invoice Total", description: "Invoice calculator for Indian freelancers: fee + GST − TDS = what reaches the bank, using the rate and section for the invoice date (s.393 of the 2025 Act; was 194J/194C) and yearly thresholds, flagging TDS on GST, the wrong rate and the no-PAN rate, with a note for the client.", category: "Sharing, sending and paying", Demo: TdsInvoiceTotalDemo },
  { name: "link-access-check", title: "Link Access Check", description: "Pre-send check for Google Drive, OneDrive, Dropbox, Notion, Figma and Box links that names which recipients can't open each one, offers fixes (give view access, open to the company, ask the owner), and warns when an anyone-with-the-link doc goes outside your organisation.", category: "Sharing, sending and paying", Demo: LinkAccessCheckDemo },
  { name: "reply-all-guard", title: "Reply All Guard", description: "Reply-all check: counts real reach with distribution lists expanded, names external recipients by domain, catches a BCC'd or forwarded-to reader about to reveal themselves and a Reply-To that points elsewhere, with sender-only or internal-only fixes and Undo.", category: "Sharing, sending and paying", Demo: ReplyAllGuardDemo },
  { name: "duplicate-payment-guard", title: "Duplicate Payment Guard", description: "Swallows a double tap (charged once), after a timeout offers Check status before paying again because the first may still land, and for a deliberate repeat says \"You paid Ravi ₹2,400 12 min ago\" and needs a separate second press.", category: "Sharing, sending and paying", Demo: DuplicatePaymentGuardDemo },
  { name: "bulk-send-guard", title: "Bulk Send Guard", description: "Before a blast, states how many it reaches, how many opted out and are excluded, who is in quiet hours in their own time zone (held by default), the cost and any jump over the last send, then needs an explicit confirm, with the count typed when the jump is big.", category: "Sharing, sending and paying", Demo: BulkSendGuardDemo },
  { name: "pii-post-guard", title: "PII Post Guard", description: "Post composer guard that says who will see the post and finds phone numbers, emails, addresses, Aadhaar, PAN, card numbers and OTPs with real checks (Verhoeff, Luhn, PAN holder type, OTP keywords) rather than loose digit runs, masking one or all the way each format expects.", category: "Sharing, sending and paying", Demo: PiiPostGuardDemo },
  { name: "recurring-charge-readback", title: "Recurring Charge Readback", description: "Readback beside a subscribe button: charged today, when the first real charge and any intro price step-up land, and the cancel-by time with zone. Flags trials too short to cancel in time and button text that disagrees with the charge.", category: "Sharing, sending and paying", Demo: RecurringChargeReadbackDemo },
  { name: "gst-invoice-check", title: "GST Invoice Check", description: "Compares the supplier GSTIN's state with the place of supply to pick CGST + SGST/UTGST or IGST (SEZ and exports always IGST), checks each rate against the slabs in force on the invoice date, LUT exports, the CGST/SGST split and the totals, with a one-tap fix.", category: "Sharing, sending and paying", Demo: GstInvoiceCheckDemo },
  { name: "role-preview", title: "Role Preview", description: "Role picker that shows exactly what the chosen role can and can't do, diffs it against the current role, and suggests the smallest role that keeps the needed abilities when the pick adds dangerous permissions.", category: "Sharing, sending and paying", Demo: RolePreviewDemo },
  { name: "visibility-picker", title: "Visibility Picker", description: "Sharing-level picker where narrowing is instant but widening (a riskier level or more people) shows who gains access and needs an explicit confirm, so a double-click or arrow key can't publish; policy-blocked levels say why, and a failed save restores the old level.", category: "Sharing, sending and paying", Demo: VisibilityPickerDemo },
  { name: "recipient-check", title: "Recipient Check", description: "Recipient field that marks external addresses in amber, catches typo'd and lookalike domains with a one-tap fix, blocks duplicates, spots a known name paired with someone else's address, and warns when a message goes to too many people.", category: "Sharing, sending and paying", Demo: RecipientCheckDemo },
  { name: "secret-paste-guard", title: "Secret Paste Guard", description: "Wraps a text field and scans its value for known key formats (AWS, GitHub, Stripe, Slack, OpenAI, Anthropic, Google, JWTs, private keys) plus long high-entropy strings, offering Redact (keeps the last 4) or Keep.", category: "Sharing, sending and paying", Demo: SecretPasteGuardDemo },
  { name: "external-link", title: "External Link", description: "Confirms off-site links with the real ASCII destination and its registrable domain in bold, and flags punycode, lookalike domains, link text that disagrees with the href, buried brand names, raw IPs and plain http.", category: "Sharing, sending and paying", Demo: ExternalLinkDemo },
  { name: "charge-summary", title: "Charge Summary", description: "Shows today's amount, the first charge and renewal dates, taxes (added or included) and one-time credits upfront, and sums it up in one plain sentence of what you'll pay.", category: "Sharing, sending and paying", Demo: ChargeSummaryDemo },
  { name: "send-time-check", title: "Send Time Check", description: "Send-time check that shows the recipient's local time on a strip of their day, flags night, after-hours, weekend (including Friday–Saturday weekends) and holidays you pass, and offers a one-tap schedule for the start of their next working day.", category: "Sharing, sending and paying", Demo: SendTimeCheckDemo },
  { name: "fill-before-copy", title: "Fill Before Copy", description: "Turns each placeholder (<YOUR_API_KEY>, {{project_id}}) into an inline field and blocks Copy, or asks once, until all of them are filled.", category: "Sharing, sending and paying", Demo: FillBeforeCopyDemo },
  { name: "photo-location-guard", title: "Photo Location Guard", description: "Pre-upload photo check that reads EXIF and XMP (GPS with its precision, capture time, camera serial, owner name, a hidden uncropped preview) and offers \"Remove location\", which re-encodes the photo upright in the browser and re-checks the result.", category: "Sharing, sending and paying", Demo: PhotoLocationGuardDemo },
  { name: "currency-hint", title: "Currency Hint", description: "Shows a foreign price with a clearly approximate, dated conversion (\"€49.00 ≈ ₹4,520\"), prices a merchant's dynamic currency conversion against the reference rate with a switch back to local currency, estimates card fees and flags stale rates.", category: "Sharing, sending and paying", Demo: CurrencyHintDemo },
  { name: "mention-guard", title: "Mention Guard", description: "Message box that says how many people @channel, @everyone or a group mention will notify and how many are in other time zones, flags mentioned people who aren't in the conversation, offers fixes, and turns Send into an explicit \"Notify 1,240 people\" confirm.", category: "Sharing, sending and paying", Demo: MentionGuardDemo },
  { name: "share-link", title: "Share Link", description: "Share-link settings read back as one sentence (\"Anyone with the link can edit until Fri 16 Oct, 5:00 PM\"), with warnings and fixes for public edit access and open-ended public links, a live expiry countdown, a flag when you widen a copied link, and confirm before revoke.", category: "Sharing, sending and paying", Demo: ShareLinkDemo },
  { name: "merge-field-check", title: "Merge Field Check", description: "Template editor for bulk email and SMS that renders the message per recipient and flags unknown fields (with typo suggestions), broken braces and recipients with no value (spaces count as empty), with one-tap fixes and fallbacks, and steps to the recipients who'd get a gap.", category: "Sharing, sending and paying", Demo: MergeFieldCheckDemo },
  { name: "forward-guard", title: "Forward Guard", description: "Lists what new recipients will see for the first time (earlier messages, internal notes, attachments, other people's addresses), skips messages they were already on, trims internal notes by default and lets each item be dropped before sending.", category: "Sharing, sending and paying", Demo: ForwardGuardDemo },
  { name: "payee-check", title: "Payee Check", description: "Payee form that asks your backend who holds the account and compares it with the typed name like Confirmation of Payee: match, close match with the real name one tap away, or no match with the name hidden and an explicit pay-anyway, plus first-payee and large-amount callouts.", category: "Sharing, sending and paying", Demo: PayeeCheckDemo },
  { name: "csv-export-guard", title: "CSV Export Guard", description: "Previews how each column opens in a spreadsheet (phone numbers and PIN codes losing leading zeros or +, long IDs becoming 1.23457E+15, \"3-4\" turning into a date, cells starting with = + - @ running as formulas) and offers per-column fixes.", category: "Sharing, sending and paying", Demo: CsvExportGuardDemo },
  { name: "link-unfurl-check", title: "Link Unfurl Check", description: "Link field that previews the unfurl (title, description, image from your Open Graph fetch) and catches localhost and staging URLs, tracking parameters, redirects (hard when they land on a sign-in page) and missing or undersized images, with fixes.", category: "Sharing, sending and paying", Demo: LinkUnfurlCheckDemo },
  { name: "qr-share", title: "QR Share", description: "QR code generator that reads the exact URL back under the code, re-decodes the matrix it drew to prove nothing was truncated, and warns about localhost, staging, http, invisible characters and dense codes, with one-tap fixes. Dependency-free encoder (byte mode, ECC M).", category: "Sharing, sending and paying", Demo: QrShareDemo },
  { name: "redact-image", title: "Redact Image", description: "Screenshot redactor with solid boxes only (blur and pixelation can be reversed), padded and snapped to whole pixels, placed by drag or keyboard, with suggestions from a pluggable text detector and a flattened, metadata-free PNG export that is re-read to check every box.", category: "Sharing, sending and paying", Demo: RedactImageDemo },
  { name: "sms-segments", title: "SMS Segments", description: "SMS composer that splits text into the parts carriers bill (160/153 GSM-7, 70/67 UCS-2), names the curly quote or emoji that forced UCS-2 (\"this ’ makes it 3 messages instead of 2\"), fixes it in one tap, and reads the total back per recipient count.", category: "Sharing, sending and paying", Demo: SmsSegmentsDemo },
  { name: "export-scope", title: "Export Scope", description: "Reads back exactly what the file holds (rows and page, filters, the date range as real dates with a day count, hidden and personal-data columns) with toggles and a one-tap \"Export all\" or \"Mask it\" fix.", category: "Sharing, sending and paying", Demo: ExportScopeDemo },
  { name: "invite-check", title: "Invite Check", description: "Pre-send invite check that shows the start in each guest's zone, offers the nearest start that suits everyone, and flags night, weekend or holiday slots, typo'd domains, no video link or location, duplicate guests (+tags, Gmail dots) and resent invites.", category: "Sharing, sending and paying", Demo: InviteCheckDemo },
  { name: "large-attachment", title: "Large Attachment", description: "Attachment size check against each service's limit, counting email's ~37% Base64 overhead, that marks the fewest files pushing it over and shows the size after sending them as a link or compressing, with an honest estimate for already-compressed files.", category: "Sharing, sending and paying", Demo: LargeAttachmentDemo },
  { name: "embed-code", title: "Embed Code", description: "Reads back what visitors will see and what the embed tracks, offers a privacy mode and allowed-site list, and catches drafts, private resources and secrets in the URL (token=, sig=) with a one-tap strip before a deliberate second click copies it.", category: "Sharing, sending and paying", Demo: EmbedCodeDemo },
  { name: "alt-text-check", title: "Alt Text Check", description: "Checks each image's alt text for missing text, filenames (IMG_2041.jpg, PXL_…), \"image of…\" redundancy, caption copies and excess length, with per-image status, one-tap fixes, a decorative toggle and a reminder when the image has words. Post jumps to the first problem.", category: "Sharing, sending and paying", Demo: AltTextCheckDemo },
  { name: "stale-reply", title: "Stale Reply", description: "Warns \"This was 3 weeks ago and 14 newer messages followed\" before you reply, surfaces the newest related messages (and any that already settled it, like \"fixed in 2.4.1\"), and offers to reply to the latest or quote the original.", category: "Sharing, sending and paying", Demo: StaleReplyDemo },
  { name: "tip-picker", title: "Tip Picker", description: "Tip picker that says whether the percent is on the pre- or post-tax amount (with a switch), shows each preset in money, flags a service charge already on the bill, and holds back accidental huge tips (250 in the % field, 15 as money, 100%) until fixed or confirmed.", category: "Sharing, sending and paying", Demo: TipPickerDemo },
  { name: "refund-picker", title: "Refund Picker", description: "Refund builder: pick units per item or a capped custom amount, see each restocking and return-shipping deduction, keep non-refundable items visible with the reason, compare each method's net and arrival dates, then read the whole refund back before issuing.", category: "Sharing, sending and paying", Demo: RefundPickerDemo },
  { name: "plan-change-readback", title: "Plan Change Readback", description: "Plan change readback that prorates by day (credit, charge today, next bill and date), says a downgrade credit goes to future bills not the card, compares now vs period end, lists lost features, and shows usage over new limits, acknowledged if destructive.", category: "Sharing, sending and paying", Demo: PlanChangeReadbackDemo },
  { name: "payment-reference", title: "Payment Reference", description: "Reference field that requires the invoice number in the expected format, checks each rail's length and character set (UPI, IMPS, NEFT, Faster Payments), moves a cut-off invoice number to the front, and previews the payee's statement line.", category: "Sharing, sending and paying", Demo: PaymentReferenceDemo },
  { name: "truncation-preview", title: "Truncation Preview", description: "Preview of where LinkedIn, Instagram, X, iOS/Android notifications and Google (by pixel width) cut the text, warning when the key phrase, a link or an @mention X won't notify sits below the fold, with fixes that move that sentence up or remove blank lines.", category: "Sharing, sending and paying", Demo: TruncationPreviewDemo },
  { name: "dockerfile-check", title: "Dockerfile Check", description: "Parses like BuildKit (escape directive, continuations, heredocs, stages) and flags a final image running as root, secrets in ARG or ENV, secret files baked in or copied across stages, COPY . before installs, no .dockerignore, apt-get hygiene, unchecked ADD URLs, curl | sh.", category: "Reading without mistakes", Demo: DockerfileCheckDemo },
  { name: "gitignore-check", title: "Gitignore Check", description: "Dependency-free .gitignore checker that applies Git's matching rules to your file list, names the line deciding each file, and flags syntax traps, ineffective ! lines, anchors that miss nested folders, missing .env/key/node_modules entries and already-tracked files.", category: "Reading without mistakes", Demo: GitignoreCheckDemo },
  { name: "workflow-yaml-guard", title: "Workflow YAML Guard", description: "GitHub Actions review: pull_request_target or workflow_run jobs that check out PR code, untrusted ${{ github.event.* }} in run scripts, actions on movable tags, missing or write-all permissions, echoed secrets and fork-reachable self-hosted runners, with one-tap fixes.", category: "Reading without mistakes", Demo: WorkflowYamlGuardDemo },
  { name: "iam-policy-check", title: "IAM Policy Check", description: "Reads each IAM or S3 bucket policy statement back in plain words (who, what, on what, under which condition) and flags admin and service:* wildcards, Resource \"*\", Principal \"*\" that S3 would call public, NotAction/NotPrincipal traps and wide iam:PassRole, with scoped fixes.", category: "Reading without mistakes", Demo: IamPolicyCheckDemo },
  { name: "hreflang-check", title: "Hreflang Check", description: "Checks pasted <link> tags or a sitemap for one page or a set, following Google Search Central: a who-links-to-whom grid, missing return links, invalid codes (en-UK, es-419), relative URLs, missing self-reference or x-default, and canonicals to another language, with fixes.", category: "Reading without mistakes", Demo: HreflangCheckDemo },
  { name: "redirect-rule-input", title: "Redirect Rule Input", description: "Redirect list checker for vercel.json, Netlify _redirects and nginx rewrite/return. Finds loops, chains, shadowed rules, open redirects, wrong status codes, dropped queries and trailing-slash traps, with a GET/POST tester and one-tap fixes.", category: "Reading without mistakes", Demo: RedirectRuleInputDemo },
  { name: "set-cookie-check", title: "Set-Cookie Check", description: "Set-Cookie checker that reads back who gets each cookie, over what, cross-site or not and for how long (after the 400-day cap), flagging SameSite=None or Partitioned without Secure, broken __Host-/__Secure- prefixes, wide Domain, missing HttpOnly and size limits.", category: "Reading without mistakes", Demo: SetCookieCheckDemo },
  { name: "qr-scan-check", title: "QR Scan Check", description: "Post-scan check showing the real domain against what's printed beside the code (with a go-to-printed-site option), flagging lookalike and brand-borrowing domains, short links (via your resolver), app downloads, and for UPI codes the payee, amount and refund scams.", category: "Reading without mistakes", Demo: QrScanCheckDemo },
  { name: "env-diff", title: "Env Diff", description: "Compares two environments key by key, lists missing and empty keys first, flags production values pointing at localhost, a test key or the staging host, and secrets reused across both, masking every secret behind a short fingerprint.", category: "Reading without mistakes", Demo: EnvDiffDemo },
  { name: "join-preview", title: "Join Preview", description: "Join preview that predicts the row count for each join type, names repeated keys that fan rows out, counts rows dropped for no match or a blank key, and catches keys that never match (number vs text, spaces, case, leading zeros), with fixes that say how many rows they rescue.", category: "Reading without mistakes", Demo: JoinPreviewDemo },
  { name: "dedupe-key-picker", title: "Dedupe Key Picker", description: "As you pick key columns, previews how many rows merge, names a near-unique column (like a timestamp) that keeps duplicates apart, flags a key so broad one value swallows many rows, keeps blank keys separate and highlights values a merge would discard.", category: "Reading without mistakes", Demo: DedupeKeyPickerDemo },
  { name: "dual-axis-guard", title: "Dual Axis Guard", description: "Catches zero baselines at different heights and independent ranges that make a +15% line and a +140% line climb together, states each series' real change, and offers one-tap \"index both to 100\" on one scale (your chart library via render prop, or built-in SVG).", category: "Reading without mistakes", Demo: DualAxisGuardDemo },
  { name: "secret-field", title: "Secret Field", description: "Read-only secret display that keeps the readable prefix (sk_live_, ghp_) and last characters, flags Live or Test keys, re-masks on a timer or when the tab is hidden, and makes copying the masked text put the real key on the clipboard.", category: "Reading without mistakes", Demo: SecretFieldDemo },
  { name: "text-diff", title: "Text Diff", description: "Word-level diff (Myers) that calls out changed numbers (30 → 14) and draws invisible changes like doubled spaces, line breaks and zero-width characters, in inline or split view, and stays fast on long documents with small changes.", category: "Reading without mistakes", Demo: TextDiffDemo },
  { name: "readback", title: "Readback", description: "Read-out display for license keys, IBANs and Wi-Fi passwords that groups characters, labels every look-alike (zero vs letter O, one vs small L), copies the clean value and offers a large show-to-someone view.", category: "Reading without mistakes", Demo: ReadbackDemo },
  { name: "copy-confirm", title: "Copy Confirm", description: "Shows exactly what was copied, refuses to copy an empty value, flags stray whitespace and invisible characters with a one-tap clean copy, and can copy formatted numbers as plain text.", category: "Reading without mistakes", Demo: CopyConfirmDemo },
  { name: "middle-truncate", title: "Middle Truncate", description: "Text that truncates in the middle to the real rendered width so the distinguishing end (a file extension, the last characters of an ID) stays visible, while copy, title and screen readers always get the full value. Never splits emoji or accents.", category: "Reading without mistakes", Demo: MiddleTruncateDemo },
  { name: "precise-number", title: "Precise Number", description: "Compact number display (₹1.2 Cr, $1.2M) that cuts instead of rounding up, puts the exact value in a tooltip that isn't clipped by tables or scroll areas, gives spoken units, offers a lakh/crore toggle that rolls the figure to its new units, and keeps percentages honest.", category: "Reading without mistakes", Demo: PreciseNumberDemo },
  { name: "unambiguous-date", title: "Unambiguous Date", description: "Date display that writes dates as \"3 Oct 2026\" with distance from today, flags numeric inputs that read two ways (DD/MM vs MM/DD) with a one-tap choice, and lets one answer apply to a whole imported column.", category: "Reading without mistakes", Demo: UnambiguousDateDemo },
  { name: "deadline", title: "Deadline", description: "Shows time left plus the exact moment in your zone and the owner's, writes midnight as the end of the day before, and turns amber when close and red when overdue.", category: "Reading without mistakes", Demo: DeadlineDemo },
  { name: "change-highlight", title: "Change Highlight", description: "Flashes a change once (at most once a second, skipped under reduced motion), keeps a ▲/▼ with good/bad colour and the previous value in a tooltip, and can tell returning visitors what changed since their last visit.", category: "Reading without mistakes", Demo: ChangeHighlightDemo },
  { name: "spell-out", title: "Spell Out", description: "Readable display for booking refs, wallet addresses, keys and passwords: grouped characters, look-alikes named under the glyph (0 zero vs O oh, 1/l/I, 5/S), NATO spelling with case when it matters, and Cyrillic look-alikes and invisible characters flagged.", category: "Reading without mistakes", Demo: SpellOutDemo },
  { name: "honest-bar", title: "Honest Bar", description: "Pure-SVG bar chart that, when the axis doesn't start at zero, draws a broken-axis mark, states the distortion (lie factor) with a one-tap Start at 0, tears and labels values past the scale, and reads exact values on hover and keyboard focus.", category: "Reading without mistakes", Demo: HonestBarDemo },
  { name: "change-readout", title: "Change Readout", description: "Shows a change both ways (₹1,200 → ₹1,500 · +₹300 · +25%), keeps percentage points apart from percent (4% → 6% is +2 pts, +50%), gives no % from a zero base or across zero, divides by |base| for negatives, adds 2.5× when a value at least doubles and marks good or bad.", category: "Reading without mistakes", Demo: ChangeReadoutDemo },
  { name: "size-context", title: "Size Context", description: "File size readback with a relatable comparison, transfer time and the equivalent in the other unit system (including what Windows shows), plus a limit check that flags the grey zone where a \"4 GB\" limit fits only if the service means GiB.", category: "Reading without mistakes", Demo: SizeContextDemo },
  { name: "sum-check", title: "Sum Check", description: "Total checker that re-adds rows in exact integer arithmetic, shows the off-by amount, points at rows that would explain it (swapped digits, slipped decimal, flipped sign, debit on the credit side) and says when the gap is only rounding, with a one-tap use-the-sum fix.", category: "Reading without mistakes", Demo: SumCheckDemo },
  { name: "status-chip", title: "Status Chip", description: "Status chip with a distinct icon shape and text per tone, a colour-blind-safe (Okabe-Ito) palette, one shared status map so meanings stay consistent, and a hover/focus tooltip explaining what the status means and what to do next.", category: "Reading without mistakes", Demo: StatusChipDemo },
  { name: "sort-indicator", title: "Sort Indicator", description: "Sortable header plus a readback that states the sort in plain words (\"Sorted by Due date, oldest first\"), warns when the order comes from a hidden column, empty values or pinned rows, and animates rows to their new place so a re-sort can be followed.", category: "Reading without mistakes", Demo: SortIndicatorDemo },
  { name: "diff-table", title: "Diff Table", description: "Marks cells that actually differ (ignoring case, spacing and 10 GB vs 10GB), offers \"Show only differences\" with a count of hidden identical rows, and shows blank cells as \"Not stated\", never a dash that reads as \"No\".", category: "Reading without mistakes", Demo: DiffTableDemo },
  { name: "amount-in-words", title: "Amount in Words", description: "Names every digit group (2 lakh · 50 thousand), spells the amount cheque-style in lakh/crore or million with paise or cents, can show the other number system alongside, and checks typed words against the figure.", category: "Reading without mistakes", Demo: AmountInWordsDemo },
  { name: "overflow-list", title: "Overflow List", description: "Chip list or avatar stack that collapses to \"+N more\" but always keeps failed items, the signed-in user and pinned items visible, and spells out what the expand button hides (\"+4 more, 1 skipped\") instead of a bare count.", category: "Reading without mistakes", Demo: OverflowListDemo },
  { name: "honest-rating", title: "Honest Rating", description: "Rating summary showing review count and star breakdown, flagging small samples with a likely range for the true score, calling out love-it-or-hate-it splits, and exposing a disclosed Bayesian score for sorting so a 5.0 from 3 reviews can't outrank a 4.6 from 900.", category: "Reading without mistakes", Demo: HonestRatingDemo },
  { name: "unit-price", title: "Unit Price", description: "Pack comparison on a common unit price (₹ per 100 g, per litre or per piece) that marks the true cheapest and catches bigger packs costing more per unit, multi-buys dearer than singles and packs that shrank at the same price, with a one-tap switch.", category: "Reading without mistakes", Demo: UnitPriceDemo },
  { name: "abbr-hint", title: "Abbr Hint", description: "Makes each abbreviation a dotted, tappable, keyboard-focusable hint instead of a hover-only <abbr title>, can spell it out on first use, exposes the expansion to screen readers, and flags terms missing from the glossary. The hint is portalled and flips to stay on screen.", category: "Reading without mistakes", Demo: AbbrHintDemo },
  { name: "error-explainer", title: "Error Explainer", description: "Says what happened, the likely cause and one next step, waits out Retry-After, warns that an ambiguous timeout on a payment may already have gone through with Check status before Retry, and gives a copyable support reference with technical details tucked away.", category: "Reading without mistakes", Demo: ErrorExplainerDemo },
  { name: "partial-period", title: "Partial Period", description: "Period comparison that compares like for like (yesterday cut at the same minute) by default, warns when the full period is chosen, hatches the bucket still filling, dims the part of yesterday not yet reached, and projects the finish, labelled as an estimate.", category: "Reading without mistakes", Demo: PartialPeriodDemo },
  { name: "gap-aware-line", title: "Gap-Aware Line", description: "Pure-SVG line chart that breaks the line at null readings, shades and labels each gap, keeps a lone reading between gaps as a dot, draws estimated points hollow with dashed segments, and backs every reading with a data table.", category: "Reading without mistakes", Demo: GapAwareLineDemo },
  { name: "fair-rank", title: "Fair Rank", description: "Ranks ties the standard competition way (1, T-2, T-2, 4) at the precision shown so equal-looking scores share a rank, shows movement since last period, and sets aside entries below a minimum sample with the reason and the rank they would have had.", category: "Reading without mistakes", Demo: FairRankDemo },
  { name: "eta-range", title: "ETA Range", description: "Quotes the range covering 90% of deliveries, with a most likely day only when one stands out (\"Thu 15 – Sat 17 Oct, most likely Fri 16\"), counts business days, holidays and the cutoff in the shipper's zone, previews the post-cutoff range and explains when it widened.", category: "Reading without mistakes", Demo: EtaRangeDemo },
  { name: "palette-guard", title: "Palette Guard", description: "Chart palette check that simulates protan, deutan and tritan vision (Machado 2009), flags every pair under a CIEDE2000 threshold, and offers the smallest lightness-only fix that clears all clashes, or patterns and direct labels when no colour change can.", category: "Reading without mistakes", Demo: PaletteGuardDemo },
]
